const TARGET_SAMPLE_RATE = 16_000;
const MAX_RECORDING_SECONDS = 90;
const DEFAULT_IDLE_RELEASE_MS = 45_000;

const RECORDER_WORKLET_SOURCE = `
class PCMRecorderProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.chunk = new Float32Array(4096);
    this.offset = 0;
    this.port.onmessage = (event) => {
      if (event.data === 'flush') this.flush();
    };
  }

  flush() {
    if (this.offset > 0) {
      const samples = this.chunk.slice(0, this.offset);
      this.port.postMessage({ type: 'chunk', samples }, [samples.buffer]);
      this.offset = 0;
    }
    this.port.postMessage({ type: 'flushed' });
  }

  process(inputs, outputs) {
    const input = inputs[0];
    const output = outputs[0];
    if (output) {
      for (const channel of output) channel.fill(0);
    }
    if (!input || input.length === 0) return true;

    const frameLength = input[0].length;
    for (let i = 0; i < frameLength; i++) {
      let mono = 0;
      for (let channel = 0; channel < input.length; channel++) {
        mono += input[channel][i] || 0;
      }
      this.chunk[this.offset++] = mono / input.length;
      if (this.offset === this.chunk.length) {
        const samples = this.chunk;
        this.port.postMessage({ type: 'chunk', samples }, [samples.buffer]);
        this.chunk = new Float32Array(4096);
        this.offset = 0;
      }
    }
    return true;
  }
}
registerProcessor('blackriver-pcm-recorder', PCMRecorderProcessor);
`;

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function makeCustomEvent(type, detail) {
  return new CustomEvent(type, { detail });
}

export class VoiceRuntime extends EventTarget {
  constructor({ idleReleaseMs = DEFAULT_IDLE_RELEASE_MS } = {}) {
    super();
    this.idleReleaseMs = idleReleaseMs;
    this.worker = null;
    this.pending = new Map();
    this.capture = null;
    this.state = 'idle';
    this.modelsReady = false;
    this.loadedMode = null;
    this.releaseTimer = null;
    this.recordingLimitTimer = null;
    this.timerInterval = null;
    this.lastRaw = '';
    this.lastCleaned = '';
  }

  emit(type, detail = {}) {
    this.dispatchEvent(makeCustomEvent(type, detail));
  }

  setState(state, detail = {}) {
    this.state = state;
    this.emit('state', { state, ...detail });
  }

  ensureWorker() {
    if (this.worker) return this.worker;
    const worker = new Worker(new URL('./voice-worker.js', import.meta.url), {
      type: 'module',
      name: 'blackriver-voice',
    });
    worker.onmessage = (event) => this.onWorkerMessage(event.data || {});
    worker.onerror = (event) => {
      const error = new Error(event.message || 'BlackRiver Voice worker failed.');
      for (const pending of this.pending.values()) pending.reject(error);
      this.pending.clear();
      try { worker.terminate(); } catch {}
      if (this.worker === worker) this.worker = null;
      this.modelsReady = false;
      this.loadedMode = null;
      this.setState('error', { message: error.message });
    };
    this.worker = worker;
    return worker;
  }

  onWorkerMessage(message) {
    const pending = message.requestId ? this.pending.get(message.requestId) : null;
    if (message.type === 'progress') {
      this.emit('progress', message);
      return;
    }
    if (message.type === 'phase') {
      if (message.phase === 'transcribing') this.setState('transcribing', { label: message.label || 'Transcribing' });
      else if (message.phase === 'normalizing') this.setState('normalizing', { label: message.label || 'Polishing' });
      this.emit('phase', message);
      return;
    }
    if (message.type === 'stream') {
      this.emit('stream', message);
      return;
    }
    if (message.type === 'stream-reset') {
      this.emit('stream-reset', message);
      return;
    }
    if (message.type === 'raw') {
      this.lastRaw = message.raw || '';
      this.emit('raw', message);
      return;
    }
    if (message.type === 'ready') {
      this.modelsReady = true;
      pending?.resolve(message);
      if (pending) this.pending.delete(message.requestId);
      return;
    }
    if (message.type === 'result') {
      this.lastRaw = message.raw || '';
      this.lastCleaned = message.cleaned || '';
      pending?.resolve(message);
      if (pending) this.pending.delete(message.requestId);
      return;
    }
    if (message.type === 'error') {
      const error = new Error(message.message || 'BlackRiver Voice failed.');
      error.name = message.name || 'Error';
      pending?.reject(error);
      if (pending) this.pending.delete(message.requestId);

      // A failed ORT/WebGPU model load can leave the dedicated voice worker's
      // GPU session in an unreliable state. Voice is deliberately disposable,
      // so reset ONLY this worker immediately. QwiVer/Wllama is a different
      // worker and remains loaded; model files stay in the browser cache.
      this.releaseModels({ reason: 'worker-error' });
      this.setState('error', { message: error.message });
      this.emit('error', { message: error.message, error });
    }
  }

  callWorker(type, payload = {}, transfer = []) {
    const worker = this.ensureWorker();
    const requestId = uid();
    const promise = new Promise((resolve, reject) => {
      this.pending.set(requestId, { resolve, reject });
    });
    worker.postMessage({ type, requestId, ...payload }, transfer);
    return promise;
  }

  clearReleaseTimer() {
    clearTimeout(this.releaseTimer);
    this.releaseTimer = null;
  }

  scheduleRelease() {
    this.clearReleaseTimer();
    if (!this.worker || this.capture) return;
    this.releaseTimer = setTimeout(() => this.releaseModels({ reason: 'idle' }), this.idleReleaseMs);
  }

  releaseModels({ reason = 'idle' } = {}) {
    this.clearReleaseTimer();
    if (this.capture) return;
    if (this.worker) this.worker.terminate();
    this.worker = null;
    const error = new DOMException('BlackRiver Voice was cancelled.', 'AbortError');
    for (const pending of this.pending.values()) pending.reject(error);
    this.pending.clear();
    this.modelsReady = false;
    this.loadedMode = null;
    this.emit('released', { reason });
  }

  async prepare(settings = {}) {
    this.clearReleaseTimer();
    if (!navigator.gpu) throw new Error('BlackRiver Voice requires WebGPU in this browser.');
    const mode = settings.mode === 'raw' ? 'raw' : 'natural';
    if (this.modelsReady && (mode === 'raw' || this.loadedMode === 'normalizer')) return;

    this.setState('loading', { label: 'Preparing BlackRiver Voice' });
    try {
      await this.callWorker('load', { settings });
      this.modelsReady = true;
      if (mode !== 'raw') this.loadedMode = 'normalizer';
      this.setState('ready', { label: 'Voice ready' });
    } catch (error) {
      if (error?.name !== 'AbortError') {
        this.releaseModels({ reason: 'error' });
        this.setState('error', { message: error?.message || 'BlackRiver Voice failed to load.' });
      }
      throw error;
    }
  }

  async startRecording(settings = {}) {
    if (this.capture) return;
    await this.prepare(settings);

    if (!navigator.mediaDevices?.getUserMedia || !window.isSecureContext) {
      throw new Error('Microphone capture requires HTTPS or localhost.');
    }

    this.clearReleaseTimer();
    let stream = null;
    let context = null;
    let workletUrl = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          channelCount: 1,
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });

      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      context = new AudioContextClass({ latencyHint: 'interactive' });
      await context.resume();

      workletUrl = URL.createObjectURL(new Blob([RECORDER_WORKLET_SOURCE], { type: 'text/javascript' }));
      await context.audioWorklet.addModule(workletUrl);
      URL.revokeObjectURL(workletUrl);
      workletUrl = null;

      const source = context.createMediaStreamSource(stream);
      const analyser = context.createAnalyser();
      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.72;

      const recorderNode = new AudioWorkletNode(context, 'blackriver-pcm-recorder', {
        numberOfInputs: 1,
        numberOfOutputs: 1,
        outputChannelCount: [1],
        channelCount: 1,
        channelCountMode: 'explicit',
      });

      // Keep the visual analyser and PCM recorder on independent branches.
      // The waveform can look alive even if a browser stops pulling an
      // analyser output chain, so the recorder taps the microphone directly.
      const analyserMute = context.createGain();
      analyserMute.gain.value = 0;

      const chunks = [];
      let resolveFlush;
      const flushPromise = new Promise((resolve) => { resolveFlush = resolve; });
      recorderNode.port.onmessage = ({ data }) => {
        if (data.type === 'chunk') chunks.push(data.samples);
        if (data.type === 'flushed') resolveFlush?.();
      };

      source.connect(analyser);
      analyser.connect(analyserMute);
      analyserMute.connect(context.destination);

      source.connect(recorderNode);
      recorderNode.connect(context.destination);

      this.capture = {
        stream,
        context,
        source,
        analyser,
        analyserMute,
        recorderNode,
        chunks,
        waveformData: new Uint8Array(analyser.fftSize),
        sampleRate: context.sampleRate,
        startedAt: performance.now(),
        flush: async () => {
          recorderNode.port.postMessage('flush');
          await Promise.race([flushPromise, new Promise((resolve) => setTimeout(resolve, 160))]);
        },
      };

      this.setState('recording', { label: 'Listening', elapsedMs: 0 });
      this.timerInterval = setInterval(() => {
        if (!this.capture) return;
        this.emit('timer', { elapsedMs: performance.now() - this.capture.startedAt });
      }, 200);
      this.recordingLimitTimer = setTimeout(() => {
        this.stopRecording(settings).catch((error) => this.emit('error', { message: error.message, error }));
      }, MAX_RECORDING_SECONDS * 1000);
    } catch (error) {
      if (workletUrl) URL.revokeObjectURL(workletUrl);
      if (!this.capture) {
        stream?.getTracks().forEach((track) => track.stop());
        if (context && context.state !== 'closed') await context.close().catch(() => {});
      }
      if (error?.name !== 'AbortError') this.setState('error', { message: error?.message || 'Could not start microphone capture.' });
      throw error;
    }
  }

  async finishCapture(discard = false) {
    if (!this.capture) return null;
    clearInterval(this.timerInterval);
    clearTimeout(this.recordingLimitTimer);
    this.timerInterval = null;
    this.recordingLimitTimer = null;

    const current = this.capture;
    this.capture = null;
    await current.flush();
    current.source.disconnect();
    current.analyser.disconnect();
    current.analyserMute?.disconnect();
    current.recorderNode.disconnect();
    current.stream.getTracks().forEach((track) => track.stop());
    await current.context.close();

    if (discard) return null;
    const totalLength = current.chunks.reduce((sum, chunk) => sum + chunk.length, 0);
    const samples = new Float32Array(totalLength);
    let offset = 0;
    for (const chunk of current.chunks) {
      samples.set(chunk, offset);
      offset += chunk.length;
    }
    return this.resample(samples, current.sampleRate, TARGET_SAMPLE_RATE);
  }

  async resample(samples, sourceRate, targetRate) {
    if (sourceRate === targetRate) return samples;
    const frameCount = Math.max(1, Math.ceil(samples.length * targetRate / sourceRate));
    const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    const offline = new OfflineContext(1, frameCount, targetRate);
    const sourceBuffer = offline.createBuffer(1, samples.length, sourceRate);
    sourceBuffer.copyToChannel(samples, 0);
    const source = offline.createBufferSource();
    source.buffer = sourceBuffer;
    source.connect(offline.destination);
    source.start(0);
    const rendered = await offline.startRendering();
    return rendered.getChannelData(0).slice();
  }

  analyzeAudio(samples) {
    let sum = 0;
    let sumSquares = 0;
    let peak = 0;
    let finite = 0;
    for (let i = 0; i < samples.length; i++) {
      const value = Number.isFinite(samples[i]) ? samples[i] : 0;
      sum += value;
      sumSquares += value * value;
      peak = Math.max(peak, Math.abs(value));
      finite++;
    }
    const mean = finite ? sum / finite : 0;
    const rms = finite ? Math.sqrt(sumSquares / finite) : 0;
    return { mean, rms, peak, samples: samples.length };
  }

  prepareAudioForAsr(samples) {
    if (!samples?.length) {
      return {
        audio: new Float32Array(),
        stats: { mean: 0, rms: 0, peak: 0, samples: 0, originalRms: 0, originalPeak: 0, gain: 1 },
      };
    }

    const initial = this.analyzeAudio(samples);
    const output = new Float32Array(samples.length);

    // Remove microphone DC bias and sanitize invalid values. Then apply a
    // conservative peak normalization only when a real signal was captured.
    let centeredPeak = 0;
    let centeredSquares = 0;
    for (let i = 0; i < samples.length; i++) {
      const value = (Number.isFinite(samples[i]) ? samples[i] : 0) - initial.mean;
      output[i] = value;
      centeredPeak = Math.max(centeredPeak, Math.abs(value));
      centeredSquares += value * value;
    }
    const centeredRms = Math.sqrt(centeredSquares / Math.max(1, output.length));

    let gain = 1;
    if (centeredPeak >= 0.001 && centeredPeak < 0.85 && centeredRms >= 0.00035) {
      gain = Math.min(12, 0.92 / centeredPeak);
      if (gain > 1.05) {
        for (let i = 0; i < output.length; i++) {
          output[i] = Math.max(-1, Math.min(1, output[i] * gain));
        }
      } else {
        gain = 1;
      }
    }

    const final = this.analyzeAudio(output);
    return {
      audio: output,
      stats: {
        ...final,
        originalRms: initial.rms,
        originalPeak: initial.peak,
        gain,
      },
    };
  }

  async stopRecording(settings = {}) {
    if (!this.capture) return null;
    this.setState('transcribing', { label: 'Transcribing' });
    const captured = await this.finishCapture(false);
    if (!captured || captured.length < TARGET_SAMPLE_RATE * 0.5) {
      this.setState('ready', { label: 'That was too short' });
      this.scheduleRelease();
      return { raw: '', cleaned: '', tooShort: true };
    }

    const { audio, stats } = this.prepareAudioForAsr(captured);
    const duration = audio.length / TARGET_SAMPLE_RATE;

    console.info(
      `[BlackRiver Voice] capture ${duration.toFixed(2)}s · ` +
      `RMS ${stats.originalRms.toFixed(5)} → ${stats.rms.toFixed(5)} · ` +
      `peak ${stats.originalPeak.toFixed(4)} → ${stats.peak.toFixed(4)} · ` +
      `gain ×${stats.gain.toFixed(2)}`,
    );
    this.emit('audio-metrics', { duration, ...stats });

    if (stats.originalPeak < 0.0008 || stats.originalRms < 0.00008) {
      this.setState('ready', { label: 'Microphone signal was too quiet' });
      this.scheduleRelease();
      return { raw: '', cleaned: '', noSignal: true, audioStats: stats };
    }

    const buffer = audio.buffer.slice(audio.byteOffset, audio.byteOffset + audio.byteLength);
    const runtimeSettings = {
      ...settings,
      locale: settings.locale || navigator.language || 'en-US',
      audioStats: stats,
    };

    try {
      const result = await this.callWorker('transcribe', { audio: buffer, settings: runtimeSettings }, [buffer]);
      this.setState('done', { label: 'Refined locally', mode: result.mode, asr: result.asr });
      this.scheduleRelease();
      return { ...result, audioStats: stats };
    } catch (error) {
      if (error?.name !== 'AbortError') this.setState('error', { message: error?.message || 'Voice transcription failed.' });
      this.scheduleRelease();
      throw error;
    }
  }

  async cancelRecording() {
    if (this.capture) await this.finishCapture(true);
    this.setState(this.modelsReady ? 'ready' : 'idle', { label: 'Cancelled' });
    this.scheduleRelease();
  }

  get analyser() {
    return this.capture?.analyser || null;
  }

  get waveformData() {
    return this.capture?.waveformData || null;
  }

  async destroy() {
    clearInterval(this.timerInterval);
    clearTimeout(this.recordingLimitTimer);
    this.clearReleaseTimer();
    if (this.capture) await this.finishCapture(true).catch(() => {});
    this.releaseModels({ reason: 'destroy' });
  }
}
