function normalizePath(path = '') {
  const parts = String(path)
    .replace(/\\/g, '/')
    .split('/')
    .filter(Boolean);
  if (parts.some((p) => p === '..')) throw new Error('Parent-directory traversal is not allowed.');
  return parts.filter((p) => p !== '.');
}

async function resolveHandle(root, path, { createFile = false, createDir = false } = {}) {
  const parts = normalizePath(path);
  let dir = root;
  for (let i = 0; i < parts.length - 1; i++) {
    dir = await dir.getDirectoryHandle(parts[i], { create: createDir });
  }
  const name = parts.at(-1);
  return { dir, name, parts };
}

async function readFile(root, path) {
  const { dir, name } = await resolveHandle(root, path);
  if (!name) throw new Error('A file path is required.');
  const handle = await dir.getFileHandle(name);
  const file = await handle.getFile();
  return file.text();
}

async function walk(dir, prefix = '', depth = 0, maxDepth = 6, out = []) {
  if (depth > maxDepth) return out;
  for await (const [name, handle] of dir.entries()) {
    if (name === 'node_modules' || name === '.git' || name === 'dist') continue;
    const path = prefix ? `${prefix}/${name}` : name;
    out.push({ path, kind: handle.kind });
    if (handle.kind === 'directory') await walk(handle, path, depth + 1, maxDepth, out);
  }
  return out;
}

function globToRegExp(glob = '**/*') {
  const escaped = String(glob)
    .replace(/\\/g, '/')
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')
    .replace(/\*\*/g, '§§DOUBLESTAR§§')
    .replace(/\*/g, '[^/]*')
    .replace(/\?/g, '[^/]')
    .replace(/§§DOUBLESTAR§§/g, '.*');
  return new RegExp(`^${escaped}$`, 'i');
}

export class ProjectWorkspace extends EventTarget {
  constructor() {
    super();
    this.root = null;
    this.name = null;
  }

  get available() {
    return typeof window.showDirectoryPicker === 'function';
  }

  async chooseDirectory() {
    if (!this.available) {
      throw new Error('This browser does not expose the File System Access API. Use a Chromium-based browser for editable Work projects.');
    }
    this.root = await window.showDirectoryPicker({ mode: 'readwrite' });
    this.name = this.root.name;
    this.dispatchEvent(new CustomEvent('project', { detail: { name: this.name } }));
    return this.root;
  }

  clear() {
    this.root = null;
    this.name = null;
    this.dispatchEvent(new CustomEvent('project', { detail: { name: null } }));
  }

  requireRoot() {
    if (!this.root) throw new Error('No Work project folder is selected.');
    return this.root;
  }

  get definitions() {
    if (!this.root) return [];
    return [
      {
        type: 'function',
        function: {
          name: 'list_directory',
          description: 'List direct files and folders inside a project-relative directory.',
          parameters: { type: 'object', properties: { path: { type: 'string', description: 'Project-relative directory. Empty string means project root.' } } },
        },
      },
      {
        type: 'function',
        function: {
          name: 'file_glob_search',
          description: 'Find project files by glob pattern, similar to llama.cpp server file_glob_search. Examples: **/*.js, src/**/*.ts, *.html.',
          parameters: {
            type: 'object',
            properties: {
              pattern: { type: 'string', description: 'Project-relative glob pattern.' },
              max_results: { type: 'number', description: 'Maximum number of matches. Default 200.' },
            },
            required: ['pattern'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'read_file',
          description: 'Read a UTF-8 text file from the selected project.',
          parameters: { type: 'object', properties: { path: { type: 'string', description: 'Project-relative file path.' } }, required: ['path'] },
        },
      },
      {
        type: 'function',
        function: {
          name: 'grep_search',
          description: 'Search text files in the project for a literal query and return matching lines.',
          parameters: {
            type: 'object',
            properties: {
              query: { type: 'string', description: 'Literal text to find.' },
              path: { type: 'string', description: 'Optional project-relative directory prefix.' },
              max_results: { type: 'number', description: 'Maximum matches. Default 50.' },
            },
            required: ['query'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'write_file',
          description: 'Create or overwrite a UTF-8 project file. User approval is required.',
          parameters: {
            type: 'object',
            properties: {
              path: { type: 'string', description: 'Project-relative file path.' },
              content: { type: 'string', description: 'Complete file content.' },
            },
            required: ['path', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'edit_file',
          description: 'Edit a project file by replacing exact text. Browser-safe counterpart of llama.cpp server edit_file. User approval is required.',
          parameters: {
            type: 'object',
            properties: {
              path: { type: 'string', description: 'Project-relative file path.' },
              search: { type: 'string', description: 'Exact existing text.' },
              replace: { type: 'string', description: 'Replacement text.' },
              replace_all: { type: 'boolean', description: 'Replace all occurrences. Default false.' },
            },
            required: ['path', 'search', 'replace'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'get_info',
          description: 'Return information about the currently connected BlackRiver Work project and browser-safe tool capabilities.',
          parameters: { type: 'object', properties: {} },
        },
      },
    ];
  }

  async execute(name, args = {}, { approve } = {}) {
    const root = this.requireRoot();
    switch (name) {
      case 'get_info': {
        return {
          project: this.name,
          root_access: 'browser-granted',
          capabilities: ['list_directory', 'file_glob_search', 'read_file', 'grep_search', 'write_file', 'edit_file'],
          shell: false,
        };
      }
      case 'file_glob_search': {
        const all = await walk(root, '', 0, 8);
        const pattern = String(args.pattern || '**/*').replace(/\\/g, '/').replace(/^\.\//, '');
        const regex = globToRegExp(pattern);
        const limit = Math.max(1, Math.min(Number(args.max_results) || 200, 500));
        const matches = all.filter((entry) => entry.kind === 'file' && regex.test(entry.path)).slice(0, limit).map((entry) => entry.path);
        return { pattern, matches, truncated: matches.length >= limit };
      }
      case 'list_directory': {
        let dir = root;
        for (const part of normalizePath(args.path || '')) dir = await dir.getDirectoryHandle(part);
        const entries = [];
        for await (const [entryName, handle] of dir.entries()) entries.push({ name: entryName, kind: handle.kind });
        entries.sort((a, b) => a.kind === b.kind ? a.name.localeCompare(b.name) : a.kind === 'directory' ? -1 : 1);
        return { path: args.path || '.', entries };
      }
      case 'read_file': {
        const content = await readFile(root, args.path);
        return { path: args.path, content };
      }
      case 'grep_search': {
        const all = await walk(root);
        const prefix = (args.path || '').replace(/\\/g, '/').replace(/^\/|\/$/g, '');
        const query = String(args.query || '');
        const limit = Math.max(1, Math.min(Number(args.max_results) || 50, 200));
        const matches = [];
        const textExt = /\.(txt|md|js|mjs|cjs|ts|tsx|jsx|json|html|css|scss|py|rs|cpp|c|h|hpp|java|go|toml|yaml|yml|ini|bat|ps1|sh|xml|svg)$/i;
        for (const entry of all) {
          if (matches.length >= limit) break;
          if (entry.kind !== 'file' || !textExt.test(entry.path)) continue;
          if (prefix && !entry.path.startsWith(prefix)) continue;
          try {
            const content = await readFile(root, entry.path);
            const lines = content.split(/\r?\n/);
            lines.forEach((line, index) => {
              if (matches.length < limit && line.includes(query)) {
                matches.push({ path: entry.path, line: index + 1, text: line.slice(0, 500) });
              }
            });
          } catch {}
        }
        return { query, matches, truncated: matches.length >= limit };
      }
      case 'write_file': {
        const ok = await approve?.({ name, args, summary: `Write ${args.path}` });
        if (ok === false) return { status: 'denied', path: args.path };
        const { dir, name: fileName, parts } = await resolveHandle(root, args.path, { createDir: true });
        if (!fileName) throw new Error('A file path is required.');
        // Ensure intermediate directories exist.
        let writeDir = root;
        for (const part of parts.slice(0, -1)) writeDir = await writeDir.getDirectoryHandle(part, { create: true });
        const handle = await writeDir.getFileHandle(fileName, { create: true });
        const writable = await handle.createWritable();
        await writable.write(String(args.content ?? ''));
        await writable.close();
        return { status: 'ok', path: args.path, bytes: new Blob([String(args.content ?? '')]).size };
      }
      case 'edit_file':
      case 'replace_in_file': {
        const before = await readFile(root, args.path);
        const search = String(args.search ?? '');
        if (!search) throw new Error('Search text cannot be empty.');
        const count = before.split(search).length - 1;
        if (!count) return { status: 'not_found', path: args.path, occurrences: 0 };
        const ok = await approve?.({ name, args: { ...args, content: undefined }, summary: `Edit ${args.path} (${args.replace_all ? count : 1} replacement${count === 1 ? '' : 's'})` });
        if (ok === false) return { status: 'denied', path: args.path };
        const after = args.replace_all ? before.split(search).join(String(args.replace ?? '')) : before.replace(search, String(args.replace ?? ''));
        const { dir, name: fileName } = await resolveHandle(root, args.path);
        const handle = await dir.getFileHandle(fileName);
        const writable = await handle.createWritable();
        await writable.write(after);
        await writable.close();
        return { status: 'ok', path: args.path, occurrences: args.replace_all ? count : 1 };
      }
      default:
        throw new Error(`Unknown Work tool: ${name}`);
    }
  }
}
