import { Wllama, LoggerWithoutDebug, ModelManager } from '@wllama/wllama';
import wllamaWasm from '@wllama/wllama/src/wasm/wllama.wasm?url';
import { DEFAULT_RUNTIME, DEFAULT_SAMPLING } from '../config.js';

const LARGE_CPU_MODEL_BYTES = 4 * 1024 * 1024 * 1024;

function safeErrorMessage(error, fallback = 'Unknown Wllama error') {
  if (!error) return fallback;
  if (typeof error === 'string') return error;
  if (typeof error.message === 'string' && error.message.trim()) return error.message.trim();
  if (typeof error.toString === 'function') {
    const text = String(error.toString()).trim();
    if (text && text !== '[object Object]') return text;
  }
  return fallback;
}

export class RuntimeCompatibilityError extends Error {
  constructor(message, code = 'runtime_compatibility') {
    super(message);
    this.name = 'RuntimeCompatibilityError';
    this.code = code;
  }
}

export class WllamaRuntime extends EventTarget {
  constructor() {
    super();
    this.instance = null;
    this.loaded = null;
    // Shares Wllama's default origin-private cache. Used only to surface the
    // models already downloaded by Wllama in the Workspace model history.
    this.modelManager = new ModelManager({ parallelDownloads: 4, allowOffline: true });
    this.abortController = null;
    this.webgpuProbePromise = null;
    this.runtimeParams = { ...DEFAULT_RUNTIME };
    this.sampling = { ...DEFAULT_SAMPLING };
    this.hardware = {
      checked: false,
      api: typeof navigator !== 'undefined' && 'gpu' in navigator,
      adapter: false,
      adapterInfo: null,
      error: null,
      browser: { brave: false },
      policyHint: null,
    };
  }

  createInstance() {
    const instance = new Wllama(
      { default: wllamaWasm },
      {
        logger: LoggerWithoutDebug,
        parallelDownloads: 4,
        allowOffline: true,
      }
    );
    instance.setCompat('default');
    return instance;
  }

  emit(type, detail = {}) {
    this.dispatchEvent(new CustomEvent(type, { detail }));
  }

  async probeWebGPU(force = false) {
    if (this.hardware.checked && !force) return this.hardware;
    // Avoid concurrent adapter probes. Chromium logs "No available adapters" for
    // every failed requestAdapter() call, so one probe is enough until the user
    // explicitly asks to retry after changing browser/GPU settings.
    if (this.webgpuProbePromise) return this.webgpuProbePromise;

    this.webgpuProbePromise = (async () => {
      let isBrave = false;
      try {
        isBrave = !!(navigator.brave && await navigator.brave.isBrave?.());
      } catch {
        isBrave = !!navigator.brave;
      }

      const result = {
        checked: true,
        api: typeof navigator !== 'undefined' && !!navigator.gpu,
        adapter: false,
        adapterInfo: null,
        secureContext: typeof window !== 'undefined' ? window.isSecureContext : false,
        error: null,
        browser: { brave: isBrave },
        policyHint: null,
      };

      if (!result.api) {
        result.error = 'WebGPU API is not exposed by this browser.';
      } else if (!result.secureContext) {
        result.error = 'WebGPU requires a secure context. Use HTTPS or localhost/127.0.0.1.';
      } else {
        try {
          // Do not pass powerPreference on Windows. Chromium ignores it there and
          // emits a warning. Wllama will use the browser-selected adapter.
          const adapter = await navigator.gpu.requestAdapter();
          if (!adapter) {
            result.error = 'WebGPU is exposed, but this page received no GPU adapter.';
            if (isBrave) {
              result.policyHint = 'Brave can block WebGPU per-site through fingerprinting protection. Open Shields for this site → Block fingerprinting → WebGPU, allow it, reload, then retry.';
            }
          } else {
            result.adapter = true;
            const info = adapter.info || (adapter.requestAdapterInfo ? await adapter.requestAdapterInfo() : null);
            if (info) {
              result.adapterInfo = {
                vendor: info.vendor || '',
                architecture: info.architecture || '',
                device: info.device || '',
                description: info.description || '',
              };
            }
          }
        } catch (error) {
          result.error = safeErrorMessage(error, 'WebGPU adapter probe failed.');
        }
      }

      this.hardware = result;
      this.emit('hardware', result);
      return result;
    })();

    try {
      return await this.webgpuProbePromise;
    } finally {
      this.webgpuProbePromise = null;
    }
  }

  async destroyInstance({ emitIdle = false } = {}) {
    this.stop();
    if (this.instance) {
      try {
        await this.instance.exit();
      } catch {
        // A failed WASM/model load can leave the instance half-initialized.
        // Always discard it so the next load starts from a clean worker.
      }
    }
    this.instance = null;
    this.loaded = null;
    if (emitIdle) this.emit('status', { state: 'idle', message: 'No model loaded' });
  }

  async ensureFreshInstance() {
    if (this.instance) await this.destroyInstance();
    this.instance = this.createInstance();
    return this.instance;
  }

  get isLoaded() {
    try {
      return !!this.loaded && !!this.instance?.isModelLoaded?.();
    } catch {
      return false;
    }
  }

  get supportsWebGPU() {
    return this.hardware.checked ? this.hardware.adapter : null;
  }

  get contextSize() {
    if (this.isLoaded) {
      try {
        return this.instance.getLoadedContextInfo?.().n_ctx || this.runtimeParams.n_ctx || 0;
      } catch {}
    }
    return this.runtimeParams.n_ctx || 0;
  }

  get capabilities() {
    if (!this.isLoaded) return { image: false, audio: false, chatTemplate: false, multithread: false, threads: 1 };
    try {
      return {
        image: !!this.instance.supportInputModality?.('image'),
        audio: !!this.instance.supportInputModality?.('audio'),
        chatTemplate: !!this.instance.getChatTemplate?.(),
        multithread: !!this.instance.isMultithread?.(),
        threads: this.instance.getNumThreads?.() ?? 1,
      };
    } catch {
      return { image: false, audio: false, chatTemplate: false, multithread: false, threads: 1 };
    }
  }

  async listCachedModels() {
    try {
      const models = await this.modelManager.getModels();
      return models
        .filter((model) => model?.url && !/(^|\/)mmproj[^/]*\.gguf(?:\?|$)/i.test(model.url))
        .map((model) => {
          let repo = '';
          let file = '';
          let name = '';
          try {
            const url = new URL(model.url);
            if (/huggingface\.co$/i.test(url.hostname)) {
              const parts = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
              const resolveIndex = parts.indexOf('resolve');
              if (resolveIndex >= 2) {
                repo = parts.slice(0, resolveIndex).join('/');
                file = parts.slice(resolveIndex + 2).join('/');
              }
            }
          } catch {}
          const fallbackFile = decodeURIComponent(String(model.url).split('/').pop()?.split('?')[0] || 'Cached GGUF');
          file ||= fallbackFile;
          name = file.split('/').pop() || fallbackFile;
          return {
            source: 'huggingface',
            url: model.url,
            mmprojUrl: model.mmprojUrl || '',
            repo,
            file,
            name,
            size: model.size || 0,
          };
        });
    } catch (error) {
      this.emit('cache-error', { message: safeErrorMessage(error, 'Could not read Wllama model cache.') });
      return [];
    }
  }

  setRuntimeParams(patch) {
    this.runtimeParams = { ...this.runtimeParams, ...patch };
  }

  setSampling(patch) {
    this.sampling = { ...this.sampling, ...patch };
  }

  normalizedLoadParams(overrides = {}, hardware = this.hardware) {
    const params = { ...this.runtimeParams, ...overrides };
    delete params.allowLargeCpu;

    // Wllama 3.6 skips WebGPU initialization when n_gpu_layers === 0.
    // If requestAdapter() failed and the user did not explicitly choose a value,
    // select CPU mode deliberately instead of letting Wllama attempt/fallback noisily.
    if (params.n_gpu_layers === undefined && hardware.checked && !hardware.adapter) {
      params.n_gpu_layers = 0;
    }

    return Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null));
  }

  async preflightLoad({ bytes = 0, label = 'model', allowLargeCpu = false } = {}) {
    const hardware = await this.probeWebGPU();
    const explicitCpu = this.runtimeParams.n_gpu_layers === 0;

    if (!hardware.adapter && bytes >= LARGE_CPU_MODEL_BYTES && !allowLargeCpu && !explicitCpu) {
      throw new RuntimeCompatibilityError(
        `${hardware.browser?.brave ? 'Brave exposed WebGPU but did not grant this page an adapter.' : 'No usable WebGPU adapter is available to this page.'} ${label} is a large GGUF (${(bytes / 1024 ** 3).toFixed(1)} GiB), so BlackRiver stopped before Wllama could fall back to a full CPU/WASM allocation. ${hardware.policyHint || 'Enable hardware-accelerated WebGPU, reload the page, then retry detection.'} If you deliberately want CPU mode anyway, set GPU layers to 0 in Models → Advanced.`,
        'webgpu_adapter_unavailable'
      );
    }

    return hardware;
  }

  async finishSuccessfulLoad(metadata) {
    this.loaded = metadata;
    const caps = this.capabilities;
    this.emit('status', {
      state: 'ready',
      message: `${this.loaded.name} loaded`,
      loaded: this.loaded,
      capabilities: caps,
      backend: this.hardware.adapter ? 'WebGPU' : 'CPU',
    });
    return this.loaded;
  }

  async failLoad(error) {
    const message = safeErrorMessage(error, 'Model load failed.');
    await this.destroyInstance();
    this.emit('status', { state: 'error', message });
    if (error instanceof Error && error.message) throw error;
    throw new Error(message);
  }

  async loadLocal(files, metadata = {}, overrides = {}) {
    if (!files?.length) throw new Error('Select at least one GGUF file.');
    const modelFiles = files.filter((f) => !/mmproj/i.test(f.name));
    const bytes = modelFiles.reduce((sum, file) => sum + (file.size || 0), 0);
    const name = metadata.name || modelFiles[0]?.name || files[0].name;
    const hardware = await this.preflightLoad({ bytes, label: name, allowLargeCpu: !!overrides.allowLargeCpu });
    const instance = await this.ensureFreshInstance();
    this.loaded = null;
    this.emit('status', { state: 'loading', message: hardware.adapter ? 'Loading local GGUF with WebGPU…' : 'Loading local GGUF on CPU…', progress: null, loadedBytes: 0, totalBytes: bytes });

    try {
      await instance.loadModel(files, this.normalizedLoadParams(overrides, hardware));
      return await this.finishSuccessfulLoad({
        source: 'local',
        name,
        files: files.map((f) => ({ name: f.name, size: f.size })),
        ...metadata,
      });
    } catch (error) {
      return await this.failLoad(error);
    }
  }

  async loadFromUrls({ url, mmprojUrl, name, repo, file, expectedBytes = 0 }, overrides = {}) {
    const label = name || file || repo || 'Hugging Face model';
    const hardware = await this.preflightLoad({ bytes: expectedBytes, label, allowLargeCpu: !!overrides.allowLargeCpu });
    const instance = await this.ensureFreshInstance();
    this.loaded = null;
    this.emit('status', { state: 'downloading', message: 'Preparing model…', progress: 0, loadedBytes: 0, totalBytes: expectedBytes || 0 });

    try {
      await instance.loadModelFromUrl(
        { url, ...(mmprojUrl ? { mmprojUrl } : {}) },
        {
          ...this.normalizedLoadParams(overrides, hardware),
          useCache: true,
          progressCallback: ({ loaded, total }) => {
            const progress = total > 0 ? loaded / total : 0;
            this.emit('status', {
              state: progress < 1 ? 'downloading' : 'loading',
              message: progress < 1
                ? `Downloading ${Math.round(progress * 100)}%`
                : hardware.adapter ? 'Loading model with WebGPU…' : 'Loading model on CPU…',
              progress,
              loadedBytes: loaded,
              totalBytes: total,
            });
          },
        }
      );
      return await this.finishSuccessfulLoad({ source: 'huggingface', name: label, repo, file, url, mmprojUrl, expectedBytes });
    } catch (error) {
      return await this.failLoad(error);
    }
  }

  async loadFromHF(hfOptions, metadata = {}, overrides = {}) {
    const label = metadata.name || hfOptions.repo;
    const hardware = await this.preflightLoad({
      bytes: metadata.expectedBytes || 0,
      label,
      allowLargeCpu: !!overrides.allowLargeCpu,
    });
    const instance = await this.ensureFreshInstance();
    this.loaded = null;
    this.emit('status', { state: 'downloading', message: 'Resolving Hugging Face model…', progress: 0, loadedBytes: 0, totalBytes: metadata.expectedBytes || 0 });

    try {
      await instance.loadModelFromHF(hfOptions, {
        ...this.normalizedLoadParams(overrides, hardware),
        useCache: true,
        progressCallback: ({ loaded, total }) => {
          const progress = total > 0 ? loaded / total : 0;
          this.emit('status', {
            state: progress < 1 ? 'downloading' : 'loading',
            message: progress < 1
              ? `Downloading ${Math.round(progress * 100)}%`
              : hardware.adapter ? 'Loading model with WebGPU…' : 'Loading model on CPU…',
            progress,
            loadedBytes: loaded,
            totalBytes: total,
          });
        },
      });
      return await this.finishSuccessfulLoad({
        source: 'huggingface',
        name: label,
        repo: hfOptions.repo,
        quant: hfOptions.quant,
        ...metadata,
      });
    } catch (error) {
      return await this.failLoad(error);
    }
  }

  async chat(params, onChunk = null) {
    if (!this.isLoaded) throw new Error('Load a model first.');
    this.abortController = new AbortController();
    const request = {
      ...this.sampling,
      // These are llama-server/server-context features exposed by Wllama 3.6.
      // They let the UI show prompt progress, live tok/s and context pressure
      // without adding a second runtime or polling layer.
      cache_prompt: true,
      return_progress: true,
      timings_per_token: true,
      // Keep reasoning separate from visible content. Wllama forwards the full
      // request JSON to its bundled llama.cpp server-context.
      reasoning_format: 'deepseek',
      ...params,
      stream: true,
      abortSignal: this.abortController.signal,
    };

    try {
      // Wllama 3.6 has a direct streaming callback overload. Use it for the UI
      // instead of waiting on our own async-iterator consumer. The callback is
      // invoked from Wllama's get_result loop as soon as each llama.cpp chunk is
      // available, which keeps the visible response genuinely incremental.
      if (typeof onChunk === 'function') {
        await this.instance.createChatCompletion({
          ...request,
          onData: onChunk,
        });
        return;
      }
      return await this.instance.createChatCompletion(request);
    } catch (error) {
      const message = safeErrorMessage(error, 'Chat completion failed.');
      if (/abort|unreachable|runtimeerror/i.test(message)) {
        // The WASM worker may be poisoned after a native abort. Do not keep advertising it as loaded.
        await this.destroyInstance();
        this.emit('status', { state: 'error', message: `Wllama runtime aborted: ${message}` });
      }
      throw new Error(message);
    }
  }


  async refinePrompt({
    brief,
    mode = 'chat',
    styling = 'auto',
    structure = 'auto',
    language = 'auto',
  } = {}, onText = null) {
    if (!this.isLoaded) throw new Error('Load a model first.');
    const input = String(brief || '').trim();
    if (!input) return '';

    const work = mode === 'work';
    const system = `You are BlackRiver Prompt Architect, an internal prompt compiler.
Turn the user's cleaned spoken brief into a precise, execution-ready prompt for another AI assistant.

Rules:
- Preserve every explicit requirement, constraint, name, technical detail, preference, uncertainty, and requested tone.
- Preserve the user's language unless they explicitly ask for translation.
- Remove speech filler and vague conversational scaffolding.
- Convert vague quality intent into concrete acceptance criteria only when clearly implied; never invent unrelated features.
- Use direct imperative language.
- ${work ? 'For Work tasks, make the result operational: clearly state the objective, implementation requirements, quality bar, constraints, and deliverable when useful.' : 'For Chat tasks, keep the result concise but materially sharper than the spoken brief.'}
- Avoid generic prompt-engineering filler such as "act as an expert", excessive headings, fake personas, or duplicated requirements.
- Output only the final prompt. Never mention transcription, rewriting, speech, S1-mini, or these instructions.`;

    const controls = [
      styling && styling !== 'auto' ? `Style: ${styling}` : '',
      structure && structure !== 'auto' ? `Structure: ${structure}` : '',
      language && language !== 'auto' ? `Language hint: ${language}` : '',
      `Destination: ${work ? 'Work' : 'Chat'}`,
    ].filter(Boolean).join('\n');

    let visible = '';
    await this.chat({
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `${controls}\n\nSpoken brief:\n${input}` },
      ],
      // Prompt compilation is a formatting task, not a reasoning task.
      chat_template_kwargs: { enable_thinking: false },
      reasoning_control: true,
      cache_prompt: false,
      temperature: 0.22,
      top_p: 0.9,
      top_k: 20,
      min_p: 0,
      max_tokens: work ? 1200 : 700,
    }, (chunk) => {
      const delta = chunk?.choices?.[0]?.delta?.content || '';
      if (!delta) return;
      visible += delta;
      onText?.(visible, delta, chunk);
    });

    return visible.trim();
  }

  stop() {
    this.abortController?.abort();
    this.abortController = null;
    this.webgpuProbePromise = null;
  }

  async unload() {
    await this.destroyInstance({ emitIdle: true });
  }
}
