const HISTORY_KEY = 'blackriver.model.history.v1';
const MAX_RECENT = 12;

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function load() {
  try {
    return safeArray(JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]'));
  } catch {
    return [];
  }
}

function save(items) {
  try {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(items.slice(0, MAX_RECENT)));
  } catch {}
}

function localKey(entry = {}) {
  const files = safeArray(entry.files).map((f) => `${f.name}:${f.size || 0}`).sort().join('|');
  return `local:${files || entry.name || 'model'}`;
}

function remoteKey(entry = {}) {
  return `remote:${entry.url || `${entry.repo || ''}:${entry.file || entry.quant || entry.name || ''}`}`;
}

export function modelHistoryKey(entry = {}) {
  return entry.source === 'local' ? localKey(entry) : remoteKey(entry);
}

export function rememberModel(entry = {}) {
  if (!entry?.name) return;
  const next = {
    source: entry.source || 'unknown',
    name: entry.name,
    repo: entry.repo || '',
    file: entry.file || '',
    quant: entry.quant || '',
    url: entry.url || '',
    mmprojUrl: entry.mmprojUrl || '',
    expectedBytes: entry.expectedBytes || entry.size || 0,
    files: safeArray(entry.files).map((f) => ({ name: f.name, size: f.size || 0 })),
    lastUsed: Date.now(),
  };
  const key = modelHistoryKey(next);
  const items = load().filter((item) => modelHistoryKey(item) !== key);
  items.unshift(next);
  save(items);
}

export function getRecentModelHistory() {
  return load().sort((a, b) => (b.lastUsed || 0) - (a.lastUsed || 0));
}
