const STORAGE_KEY = 'blackriver.workspace.artifacts.v05';

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

export class ArtifactStore extends EventTarget {
  constructor() {
    super();
    this.items = this.load();
    this.activeId = null;
  }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.items));
    this.dispatchEvent(new Event('change'));
  }

  list(conversationId = null) {
    const items = conversationId
      ? this.items.filter((item) => item.conversationId === conversationId)
      : [...this.items];
    return items.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  get(id) {
    return this.items.find((item) => item.id === id) || null;
  }

  open(id) {
    if (!this.get(id)) return null;
    this.activeId = id;
    this.dispatchEvent(new CustomEvent('open', { detail: this.get(id) }));
    return this.get(id);
  }

  close() {
    this.activeId = null;
    this.dispatchEvent(new Event('close'));
  }

  create({ title = 'Untitled artifact', type = 'html', language = '', content = '', conversationId = null } = {}) {
    const now = Date.now();
    const item = {
      id: uid(),
      conversationId,
      title: String(title || 'Untitled artifact').slice(0, 180),
      type: ['html', 'code', 'text', 'markdown'].includes(type) ? type : 'text',
      language: String(language || ''),
      content: String(content ?? ''),
      createdAt: now,
      updatedAt: now,
    };
    this.items.unshift(item);
    this.activeId = item.id;
    this.save();
    this.dispatchEvent(new CustomEvent('created', { detail: item }));
    return item;
  }

  update(id, patch = {}) {
    const item = this.get(id);
    if (!item) throw new Error(`Artifact not found: ${id}`);
    if (patch.title !== undefined) item.title = String(patch.title || item.title).slice(0, 180);
    if (patch.content !== undefined) item.content = String(patch.content ?? '');
    if (patch.language !== undefined) item.language = String(patch.language || '');
    if (patch.type !== undefined && ['html', 'code', 'text', 'markdown'].includes(patch.type)) item.type = patch.type;
    item.updatedAt = Date.now();
    this.activeId = item.id;
    this.save();
    this.dispatchEvent(new CustomEvent('updated', { detail: item }));
    return item;
  }

  remove(id) {
    this.items = this.items.filter((item) => item.id !== id);
    if (this.activeId === id) this.activeId = null;
    this.save();
  }

  get definitions() {
    return [
      {
        type: 'function',
        function: {
          name: 'create_artifact',
          description: 'Create a complete artifact shown in the BlackRiver Work artifact viewer. Use this for self-contained HTML apps/games, code, documents, or markdown when the user asks you to build or create something and no project file needs to be edited.',
          parameters: {
            type: 'object',
            properties: {
              title: { type: 'string', description: 'Short human-readable artifact title.' },
              type: { type: 'string', enum: ['html', 'code', 'text', 'markdown'], description: 'Artifact kind. Use html for interactive webpages/apps/games.' },
              language: { type: 'string', description: 'Language label such as html, javascript, python, markdown. Optional.' },
              content: { type: 'string', description: 'Complete artifact content. For HTML, provide one self-contained HTML document with inline CSS and JavaScript.' },
            },
            required: ['title', 'type', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'update_artifact',
          description: 'Replace or revise an existing BlackRiver artifact. Prefer targeted updates only when you have read the current artifact first.',
          parameters: {
            type: 'object',
            properties: {
              artifact_id: { type: 'string', description: 'Artifact id returned by create_artifact or list_artifacts.' },
              title: { type: 'string', description: 'Optional new title.' },
              content: { type: 'string', description: 'Complete replacement content.' },
            },
            required: ['artifact_id', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'read_artifact',
          description: 'Read an existing artifact before editing it.',
          parameters: {
            type: 'object',
            properties: {
              artifact_id: { type: 'string', description: 'Artifact id.' },
            },
            required: ['artifact_id'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'list_artifacts',
          description: 'List artifacts created in the current conversation.',
          parameters: { type: 'object', properties: {} },
        },
      },
    ];
  }

  async execute(name, args = {}, { conversationId = null } = {}) {
    switch (name) {
      case 'create_artifact': {
        const item = this.create({ ...args, conversationId });
        return {
          status: 'ok',
          artifact_id: item.id,
          title: item.title,
          type: item.type,
          language: item.language,
          bytes: new Blob([item.content]).size,
          viewer: 'opened',
        };
      }
      case 'update_artifact': {
        const item = this.update(args.artifact_id, {
          title: args.title,
          content: args.content,
        });
        return {
          status: 'ok',
          artifact_id: item.id,
          title: item.title,
          type: item.type,
          bytes: new Blob([item.content]).size,
          viewer: 'opened',
        };
      }
      case 'read_artifact': {
        const item = this.get(args.artifact_id);
        if (!item) throw new Error(`Artifact not found: ${args.artifact_id}`);
        return {
          artifact_id: item.id,
          title: item.title,
          type: item.type,
          language: item.language,
          content: item.content,
        };
      }
      case 'list_artifacts': {
        return {
          artifacts: this.list(conversationId).map((item) => ({
            artifact_id: item.id,
            title: item.title,
            type: item.type,
            language: item.language,
            updated_at: item.updatedAt,
          })),
        };
      }
      default:
        throw new Error(`Unknown artifact tool: ${name}`);
    }
  }
}
