const CHAT_SYSTEM = `You are BlackRiver, a precise local AI assistant running privately on the user's device. Be useful, technically competent, concise by default, and never claim to have used tools you were not given.`;

function workSystem({ hasProject, hasArtifacts }) {
  return `You are BlackRiver Work, an agentic local workspace assistant running privately on the user's device.

Behavior rules:
- Act instead of narrating what you are about to do.
- When the user asks you to create, build, implement, write, redesign, or generate an app, webpage, game, document, code artifact, or similar deliverable, use the available artifact/project tools immediately. Do not repeatedly say you will inspect or start.
- For standalone apps, games, webpages, demos, documents, and code that do not need an existing project folder, create or update a BlackRiver artifact. Interactive artifacts should be one self-contained HTML document with inline CSS/JS unless the user asks otherwise.
- ${hasProject ? 'A project folder is connected. Read relevant files before editing them and keep changes targeted.' : 'No project folder is connected. Do not claim to inspect a filesystem. Use artifacts for creation tasks.'}
- ${hasArtifacts ? 'Existing artifacts may be read and updated when relevant.' : 'There may be no existing artifacts yet.'}
- Never invent tool results or claim a write succeeded unless the tool result confirms it.
- If a write is denied, continue without pressuring the user.
- Tool calls should contain the complete required arguments. When calling a tool, do not add a suffix after the tool call.
- After completing tool work, give a short useful result summary rather than repeating the implementation in chat.`;
}

function toOaiMessages(messages) {
  return messages
    .filter((m) => m.role === 'user' || m.role === 'assistant')
    .map((m) => {
      const out = { role: m.role, content: m.content || '' };
      // llama.cpp's reasoning parser accepts reasoning_content on assistant
      // messages. Keeping it in-context matters for thinking models across turns.
      if (m.role === 'assistant' && m.reasoning) out.reasoning_content = m.reasoning;
      return out;
    });
}

function mergeToolDelta(map, tc) {
  const index = tc.index ?? 0;
  if (!map[index]) map[index] = { id: '', name: '', arguments: '' };
  if (tc.id) map[index].id = tc.id;
  if (tc.function?.name) map[index].name += tc.function.name;
  if (tc.function?.arguments) map[index].arguments += tc.function.arguments;
}

function mergeReasoning(base = '', extra = '') {
  const a = String(base || '').trim();
  const b = String(extra || '').trim();
  if (!b) return a;
  if (!a) return b;
  if (a.includes(b)) return a;
  if (b.includes(a)) return b;
  return `${a}\n${b}`.trim();
}

// Incremental fallback for models/templates that leave <think> markup in content.
// Crucially, an unterminated <think> block is treated as live reasoning instead
// of being flashed to the user as raw assistant text while generation is running.
function splitInlineReasoning(raw = '') {
  let text = String(raw || '').replace(/<\|im_(?:start|end)\|>/g, '');
  let reasoning = '';
  const open = text.search(/<think>/i);
  if (open >= 0) {
    const before = text.slice(0, open);
    const afterOpen = text.slice(open).replace(/^<think>/i, '');
    const close = afterOpen.search(/<\/think>/i);
    if (close >= 0) {
      reasoning = afterOpen.slice(0, close).trim();
      text = `${before}${afterOpen.slice(close).replace(/^<\/think>/i, '')}`;
    } else {
      reasoning = afterOpen.trim();
      text = before;
    }
  } else if (/<\/think>/i.test(text)) {
    const parts = text.split(/<\/think>/i);
    const visible = parts.pop() || '';
    reasoning = parts.join('\n').trim();
    text = visible;
  }
  text = text.replace(/<\/?think>/gi, '').trimStart();
  return { content: text, reasoning };
}

function stripToolMarkup(text = '') {
  return String(text)
    .replace(/<tool_call>[\s\S]*?<\/tool_call>/gi, '')
    .replace(/<function=[^>]+>[\s\S]*?<\/function>/gi, '')
    .trim();
}

function parseScalar(value) {
  const s = String(value ?? '').trim();
  if (!s) return '';
  try { return JSON.parse(s); } catch {}
  if (s === 'true') return true;
  if (s === 'false') return false;
  if (s === 'null') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(s)) return Number(s);
  return s;
}

function parseFallbackToolCalls(raw = '') {
  const calls = [];
  const blocks = String(raw).match(/<tool_call>[\s\S]*?<\/tool_call>/gi) || [];
  for (const block of blocks) {
    const fn = block.match(/<function=([^>]+)>/i)?.[1]?.trim();
    if (!fn) continue;
    const args = {};
    const paramRegex = /<parameter=([^>]+)>\s*([\s\S]*?)\s*<\/parameter>/gi;
    let m;
    while ((m = paramRegex.exec(block))) args[m[1].trim()] = parseScalar(m[2]);
    calls.push({ id: '', name: fn, arguments: JSON.stringify(args) });
  }
  return calls;
}

function shouldRequireTool(mode, prompt, tools) {
  if (mode !== 'work' || !tools.length) return false;
  const creationIntent = /\b(create|build|make|implement|write|generate|develop|remake|redesign|produce|craft)\b/i.test(prompt || '');
  const artifactIntent = /\b(game|app|website|webpage|html|artifact|document|file|code|script|project|component|prototype)\b/i.test(prompt || '');
  return creationIntent && artifactIntent;
}

function toolActivityLabel(name = '') {
  const labels = {
    create_artifact: 'Building artifact',
    update_artifact: 'Updating artifact',
    read_artifact: 'Reading artifact',
    list_artifacts: 'Checking artifacts',
    list_directory: 'Inspecting project',
    file_glob_search: 'Finding files',
    read_file: 'Reading file',
    grep_search: 'Searching project',
    write_file: 'Writing file',
    edit_file: 'Editing file',
    replace_in_file: 'Editing file',
    get_info: 'Checking project',
  };
  return labels[name] || `Using ${String(name).replaceAll('_', ' ')}`;
}

function safeJson(text) {
  try { return JSON.parse(text || '{}'); }
  catch { return null; }
}

function normalizeMetrics(chunk, contextSize = 0) {
  const timings = chunk?.timings || {};
  const usage = chunk?.usage || {};
  const progress = chunk?.prompt_progress || null;
  const promptTokens = Number(usage.prompt_tokens ?? ((timings.cache_n || 0) + (timings.prompt_n || 0))) || 0;
  const completionTokens = Number(usage.completion_tokens ?? timings.predicted_n) || 0;
  const used = Number(usage.total_tokens) || (promptTokens + completionTokens);
  const ctx = Number(contextSize) || 0;
  return {
    promptTokens,
    completionTokens,
    used,
    remaining: ctx ? Math.max(0, ctx - used) : 0,
    contextSize: ctx,
    cachedTokens: Number(timings.cache_n || usage.prompt_tokens_details?.cached_tokens) || 0,
    promptTps: Number(timings.prompt_per_second) || 0,
    generationTps: Number(timings.predicted_per_second) || 0,
    promptProgress: progress ? {
      total: Number(progress.total) || 0,
      cache: Number(progress.cache) || 0,
      processed: Number(progress.processed) || 0,
      timeMs: Number(progress.time_ms) || 0,
    } : null,
  };
}


const REASONING_BUDGETS = Object.freeze({
  low: 512,
  medium: 2048,
  high: 8192,
});

function reasoningRequestOptions(profile = 'medium') {
  const effort = ['off', 'low', 'medium', 'high'].includes(profile) ? profile : 'medium';
  if (effort === 'off') {
    // Match llama.cpp WebUI semantics: disable thinking through the chat
    // template rather than forcing a zero-token budget.
    return {
      chat_template_kwargs: { enable_thinking: false },
      reasoning_control: true,
    };
  }
  return {
    chat_template_kwargs: { enable_thinking: true },
    thinking_budget_tokens: REASONING_BUDGETS[effort],
    reasoning_control: true,
  };
}

export class AgentHarness {
  constructor(runtime, project, artifacts) {
    this.runtime = runtime;
    this.project = project;
    this.artifacts = artifacts;
    this.maxTurns = 12;
  }

  toolDefinitions(mode) {
    if (mode !== 'work') return [];
    return [
      ...this.artifacts.definitions,
      ...(this.project.root ? this.project.definitions : []),
    ];
  }

  async executeTool(name, args, context) {
    if (this.artifacts.definitions.some((t) => t.function.name === name)) {
      return this.artifacts.execute(name, args, { conversationId: context.conversationId });
    }
    return this.project.execute(name, args, { approve: context.approve });
  }

  async run({ mode, messages, attachment, conversationId, reasoningProfile = 'medium', onText, onReasoning, onTool, onArtifact, onState, onMetrics, approve }) {
    const tools = this.toolDefinitions(mode);
    const hasProject = !!this.project.root;
    const hasArtifacts = this.artifacts.list(conversationId).length > 0;
    const system = mode === 'work' ? workSystem({ hasProject, hasArtifacts }) : CHAT_SYSTEM;
    const oai = [{ role: 'system', content: system }, ...toOaiMessages(messages)];

    if (attachment && oai.length > 1) {
      const last = oai.at(-1);
      if (last.role === 'user') {
        last.content = [
          { type: attachment.type, data: attachment.data },
          { type: 'text', text: typeof last.content === 'string' ? last.content : '' },
        ];
      }
    }

    const lastUser = [...messages].reverse().find((m) => m.role === 'user')?.content || '';
    const requireToolInitially = shouldRequireTool(mode, lastUser, tools);
    let visible = '';
    let reasoningVisible = '';
    let lastMetrics = null;
    const executedFingerprints = new Map();

    for (let turn = 0; turn < this.maxTurns; turn++) {
      onState?.({ phase: 'prefill', label: turn === 0 ? 'Reading context' : 'Continuing' });
      let rawContent = '';
      let turnReasoning = '';
      let finishReason = null;
      let sawVisibleContent = false;
      let sawReasoning = false;
      const toolMap = {};
      const announcedTools = new Set();

      await this.runtime.chat({
        messages: oai,
        ...reasoningRequestOptions(reasoningProfile),
        ...(tools.length ? {
          tools,
          tool_choice: turn === 0 && requireToolInitially ? 'required' : 'auto',
        } : {}),
      }, (chunk) => {
        const metrics = normalizeMetrics(chunk, this.runtime.contextSize);
        if (metrics.promptProgress || metrics.generationTps || metrics.promptTps || metrics.used) {
          lastMetrics = {
            ...(lastMetrics || {}),
            ...metrics,
            promptTps: metrics.promptTps || lastMetrics?.promptTps || 0,
            generationTps: metrics.generationTps || lastMetrics?.generationTps || 0,
            promptProgress: metrics.promptProgress || lastMetrics?.promptProgress || null,
          };
          onMetrics?.(lastMetrics);
          if (metrics.promptProgress && !sawReasoning && !sawVisibleContent) {
            const { processed, total } = metrics.promptProgress;
            const pct = total > 0 ? Math.min(100, Math.round((processed / total) * 100)) : 0;
            onState?.({ phase: 'prefill', label: pct > 0 && pct < 100 ? `Reading context · ${pct}%` : 'Reading context' });
          }
        }

        const choice = chunk?.choices?.[0];
        if (!choice) return;
        finishReason = choice.finish_reason ?? finishReason;
        const delta = choice.delta || {};

        // llama.cpp reasoning_format=deepseek streams this field independently.
        // Wllama forwards the JSON even though older TS typings did not enumerate it.
        const reasoningDelta = delta.reasoning_content ?? delta.reasoning ?? '';
        if (reasoningDelta) {
          turnReasoning += reasoningDelta;
          sawReasoning = true;
          onState?.({ phase: 'thinking', label: 'Thinking' });
        }

        if (delta.content) {
          rawContent += delta.content;
          const inline = splitInlineReasoning(rawContent);
          if (inline.reasoning) {
            sawReasoning = true;
            onState?.({ phase: 'thinking', label: 'Thinking' });
          }
          if (inline.content) {
            sawVisibleContent = true;
            onState?.({ phase: 'responding', label: 'Responding' });
          }
        }

        for (const tc of delta.tool_calls || []) {
          mergeToolDelta(toolMap, tc);
          const entry = toolMap[tc.index ?? 0];
          if (entry?.name && !announcedTools.has(entry.name)) {
            announcedTools.add(entry.name);
            onState?.({ phase: 'tool', label: toolActivityLabel(entry.name) });
          }
        }

        const inline = splitInlineReasoning(rawContent);
        const cleanContent = stripToolMarkup(inline.content);
        const currentReasoning = mergeReasoning(reasoningVisible, mergeReasoning(turnReasoning, inline.reasoning));
        onText?.(visible + cleanContent);
        onReasoning?.(currentReasoning);
      });

      const inline = splitInlineReasoning(rawContent);
      const cleanContent = stripToolMarkup(inline.content);
      turnReasoning = mergeReasoning(turnReasoning, inline.reasoning);
      reasoningVisible = mergeReasoning(reasoningVisible, turnReasoning);

      let calls = Object.values(toolMap).filter((tc) => tc.name);
      if (!calls.length) calls = parseFallbackToolCalls(rawContent);

      if (!calls.length) {
        visible += cleanContent;
        onText?.(visible);
        onReasoning?.(reasoningVisible);
        onState?.({ phase: 'done', label: 'Done' });
        return { content: visible.trim(), reasoning: reasoningVisible, finishReason, metrics: lastMetrics };
      }

      if (cleanContent && !/^(i(?:'ll| will| am)|let me|i'm going to)\b/i.test(cleanContent.trim())) {
        visible += `${cleanContent.trim()}\n`;
      }

      const assistantToolMessage = {
        role: 'assistant',
        content: cleanContent || null,
        ...(turnReasoning ? { reasoning_content: turnReasoning } : {}),
        tool_calls: calls.map((tc, index) => ({
          id: tc.id || `call_${turn}_${index}_${Math.random().toString(16).slice(2, 8)}`,
          type: 'function',
          function: { name: tc.name, arguments: tc.arguments || '{}' },
        })),
      };
      oai.push(assistantToolMessage);

      for (const call of assistantToolMessage.tool_calls) {
        const args = safeJson(call.function.arguments);
        if (args === null) {
          const result = { error: 'Invalid JSON arguments returned by the model.' };
          oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args: {}, result });
          continue;
        }

        const fingerprint = `${call.function.name}:${JSON.stringify(args)}`;
        const count = (executedFingerprints.get(fingerprint) || 0) + 1;
        executedFingerprints.set(fingerprint, count);
        if (count > 2) {
          const result = { error: 'Duplicate tool call suppressed. Use the existing result and continue.' };
          oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args, result });
          continue;
        }

        onTool?.({ phase: 'call', name: call.function.name, args });
        onState?.({ phase: 'tool', label: toolActivityLabel(call.function.name) });
        let result;
        try {
          result = await this.executeTool(call.function.name, args, { conversationId, approve });
        } catch (error) {
          result = { error: error?.message || String(error || 'Tool failed') };
        }
        onTool?.({ phase: 'result', name: call.function.name, args, result });
        if (result?.artifact_id && result?.viewer === 'opened') {
          this.artifacts.open(result.artifact_id);
          onArtifact?.(this.artifacts.get(result.artifact_id));
        }
        oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
      }
    }

    onState?.({ phase: 'done', label: 'Turn limit reached' });
    return {
      content: visible.trim() || 'I reached the Work turn limit before completing the task.',
      reasoning: reasoningVisible,
      finishReason: 'length',
      maxTurnsReached: true,
      metrics: lastMetrics,
    };
  }
}
