function escapeHtml(value = '') {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function errorMessage(error, fallback = 'Something went wrong.') {
  if (!error) return fallback;
  if (typeof error === 'string') return error;
  return error.message || String(error) || fallback;
}

function formatDate(ts) {
  const d = new Date(ts);
  const today = new Date();
  if (d.toDateString() === today.toDateString()) return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  return d.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

function compactToolPayload(value) {
  if (value == null) return value;
  const json = JSON.stringify(value);
  if (json.length <= 700) return value;
  return { summary: `${json.slice(0, 680)}…` };
}

function inlineMarkdown(text) {
  return text
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>');
}

function renderMarkdown(source = '', { streaming = false } = {}) {
  let renderSource = String(source || '');
  if (streaming) {
    const fences = renderSource.match(/```/g)?.length || 0;
    if (fences % 2 === 1) renderSource += '\n```';
  }
  const escaped = escapeHtml(renderSource);
  const codeBlocks = [];
  let text = escaped.replace(/```([\w+-]*)\n([\s\S]*?)```/g, (_, lang, code) => {
    const id = codeBlocks.length;
    codeBlocks.push(`<div class="code-block"><div class="code-head"><span>${escapeHtml(lang || 'code')}</span><button data-copy-code="${id}">Copy</button></div><pre><code>${code}</code></pre></div>`);
    return `@@CODE_${id}@@`;
  });

  const lines = text.split(/\r?\n/);
  const out = [];
  let listOpen = false;
  for (const line of lines) {
    const codeMatch = line.match(/^@@CODE_(\d+)@@$/);
    if (codeMatch) {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push(codeBlocks[Number(codeMatch[1])]);
      continue;
    }
    if (/^###\s+/.test(line)) {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push(`<h3>${inlineMarkdown(line.replace(/^###\s+/, ''))}</h3>`);
    } else if (/^##\s+/.test(line)) {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push(`<h2>${inlineMarkdown(line.replace(/^##\s+/, ''))}</h2>`);
    } else if (/^#\s+/.test(line)) {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push(`<h1>${inlineMarkdown(line.replace(/^#\s+/, ''))}</h1>`);
    } else if (/^[-*]\s+/.test(line)) {
      if (!listOpen) { out.push('<ul>'); listOpen = true; }
      out.push(`<li>${inlineMarkdown(line.replace(/^[-*]\s+/, ''))}</li>`);
    } else if (!line.trim()) {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push('<div class="md-gap"></div>');
    } else {
      if (listOpen) { out.push('</ul>'); listOpen = false; }
      out.push(`<p>${inlineMarkdown(line)}</p>`);
    }
  }
  if (listOpen) out.push('</ul>');
  return out.join('');
}

