function toolDetail(tool) {
  const a = tool.args || {};
  if (a.path) return a.path;
  if (a.title) return a.title;
  if (a.query) return `“${a.query}”`;
  if (a.artifact_id) return a.artifact_id.slice(0, 8);
  return '';
}

