function renderToolEvents(tools = []) {
  const rows = [];
  const pending = [];

  for (const tool of tools) {
    if (tool.phase === 'call') {
      pending.push(tool);
      continue;
    }
    if (tool.phase !== 'result') continue;

    // Pair the result with the most recent unresolved call of the same tool so
    // the UI shows one compact lifecycle row instead of a call/result duplicate.
    const idx = [...pending].reverse().findIndex((p) => p.name === tool.name);
    if (idx >= 0) pending.splice(pending.length - 1 - idx, 1);
    rows.push({ ...tool, pending: false });
  }
  rows.push(...pending.map((tool) => ({ ...tool, pending: true })));

  if (!rows.length) return '';
  return `<div class="tool-events">${rows.map((tool) => `
    <div class="tool-event ${tool.pending ? 'pending' : ''} ${tool.result?.error ? 'error' : ''}">
      <span class="tool-icon">${tool.pending ? '<span class="mini-spinner"></span>' : (tool.result?.error ? '!' : '✓')}</span>
      <span class="tool-copy"><strong>${escapeHtml(tool.pending ? toolPendingLabel(tool.name) : toolLabel(tool.name))}</strong>${toolDetail(tool) ? `<small>${escapeHtml(toolDetail(tool))}</small>` : ''}</span>
    </div>`).join('')}</div>`;
}

function formatCompactNumber(value = 0) {
  const n = Number(value) || 0;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}m`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}k`;
  return String(Math.round(n));
}

function formatElapsed(ms = 0) {
  const seconds = Math.max(0, Number(ms) || 0) / 1000;
  return seconds < 10 ? `${seconds.toFixed(1)}s` : `${Math.round(seconds)}s`;
}

function isNearBottom() {
  const distance = els.scroller.scrollHeight - els.scroller.scrollTop - els.scroller.clientHeight;
  return distance < 130;
}

function scrollConversation({ force = false } = {}) {
  if (force || isNearBottom()) els.scroller.scrollTop = els.scroller.scrollHeight;
}

function reasoningHtml(message, { streaming = false } = {}) {
  const reasoning = String(message.reasoning || '').trim();
  const elapsed = formatElapsed(message.elapsedMs || 0);
  if (!reasoning) return '';
  const live = streaming && message.live;
  const summary = live ? `Thinking · ${elapsed}` : `Thought for ${elapsed}`;
  return `<details class="reasoning ${live ? 'live' : ''}" ${live && message.phase === 'thinking' ? 'open' : ''}><summary><span class="thinking-dot"></span><span>${summary}</span></summary><div>${escapeHtml(reasoning)}</div></details>`;
}

function activityHtml(message) {
  if (!message.live) return '';
  const label = escapeHtml(message.activity || 'Thinking');
  const phase = escapeHtml(message.phase || 'prefill');
  return `<div class="live-activity ${phase}"><span class="activity-orb"><span></span></span><span class="activity-label">${label}</span><span class="activity-elapsed">${formatElapsed(message.elapsedMs || 0)}</span></div>`;
}

function formatInferenceCaption(metrics = lastInferenceMetrics) {
  if (!metrics) return `Wllama 3.6 · ${runtime.hardware.adapter ? 'WebGPU' : 'local'}`;
  const ctx = Number(metrics.contextSize || runtime.contextSize || 0);
  const used = Number(metrics.used || 0);
  const gen = Number(metrics.generationTps || 0);
  const prompt = Number(metrics.promptTps || 0);
  const speed = gen > 0 ? `${gen.toFixed(gen >= 100 ? 0 : 1)} tok/s` : prompt > 0 ? `${prompt.toFixed(prompt >= 100 ? 0 : 1)} tok/s prefill` : '';
  const context = ctx ? `${formatCompactNumber(used)} / ${formatCompactNumber(ctx)} ctx` : '';
  return [speed, context].filter(Boolean).join(' · ') || `Wllama 3.6 · ${runtime.hardware.adapter ? 'WebGPU' : 'local'}`;
}

function updateInferenceCaption(metrics = lastInferenceMetrics) {
  if (metrics) lastInferenceMetrics = { ...(lastInferenceMetrics || {}), ...metrics };
  els.composerCaption.textContent = formatInferenceCaption(lastInferenceMetrics);
  const m = lastInferenceMetrics;
  if (m) {
    const remaining = Number(m.remaining || 0);
    const cache = Number(m.cachedTokens || 0);
    els.composerCaption.title = [
      m.promptTps ? `Prefill ${m.promptTps.toFixed(1)} tok/s` : '',
      m.generationTps ? `Generation ${m.generationTps.toFixed(1)} tok/s` : '',
      cache ? `${formatCompactNumber(cache)} cached tokens` : '',
      m.contextSize ? `${formatCompactNumber(remaining)} context tokens remaining` : '',
    ].filter(Boolean).join(' · ');
  } else {
    els.composerCaption.title = '';
  }
}

function startActivityTicker(message) {
  clearInterval(activityTicker);
  activityTicker = setInterval(() => {
    if (!message.live) return;
    message.elapsedMs = performance.now() - activeTurnStart;
    const row = document.querySelector(`[data-message-id="${CSS.escape(message.id)}"]`);
    row?.querySelectorAll('.activity-elapsed').forEach((el) => { el.textContent = formatElapsed(message.elapsedMs); });
    const summary = row?.querySelector('.reasoning.live summary span:nth-child(2)');
    if (summary) summary.textContent = `Thinking · ${formatElapsed(message.elapsedMs)}`;
  }, 100);
}

