function setModelLoadProgress(detail = {}) {
  modelLoadLastStatus = detail;
  if (activeModal !== 'Models') return;
  const shell = document.getElementById('modelLoadStatus');
  const title = document.getElementById('modelLoadTitle');
  const meta = document.getElementById('modelLoadMeta');
  const percent = document.getElementById('modelLoadPercent');
  const bar = document.getElementById('modelLoadBar');
  if (!shell || !title || !meta || !percent || !bar) return;

  const state = detail.state || 'loading';
  if (!['downloading', 'loading', 'ready', 'error'].includes(state)) {
    shell.classList.add('hidden');
    return;
  }

  shell.classList.remove('hidden', 'success', 'error');
  shell.classList.toggle('success', state === 'ready');
  shell.classList.toggle('error', state === 'error');
  title.textContent = detail.message || (state === 'downloading' ? 'Downloading model…' : state === 'ready' ? 'Model ready' : 'Loading model…');

  const loaded = Number(detail.loadedBytes || 0);
  const total = Number(detail.totalBytes || 0);
  const progress = Number.isFinite(detail.progress) ? Math.max(0, Math.min(1, detail.progress)) : null;
  const determinate = state === 'downloading' && progress != null && total > 0;
  bar.classList.toggle('indeterminate', !determinate && state !== 'ready' && state !== 'error');
  bar.querySelector('span').style.width = state === 'ready' ? '100%' : determinate ? `${Math.round(progress * 100)}%` : state === 'error' ? '100%' : '28%';
  percent.textContent = state === 'ready' ? '100%' : determinate ? `${Math.round(progress * 100)}%` : '';

  if (loaded > 0 && total > 0) meta.textContent = `${humanBytes(loaded)} / ${humanBytes(total)}`;
  else if (state === 'loading') meta.textContent = 'Preparing weights and WebGPU buffers';
  else if (state === 'error') meta.textContent = 'Load failed';
  else meta.textContent = 'Local model cache';
}

function beginModelLoad(message = 'Preparing model…') {
  setModelLoadProgress({ state: 'loading', message, progress: null, loadedBytes: 0, totalBytes: 0 });
}

function cachedModelDisplayName(entry = {}) {
  const recommended = RECOMMENDED_MODELS.find((model) => entry.repo && model.repo === entry.repo);
  if (recommended) return recommended.name;
  return (entry.file || entry.name || 'Cached GGUF').split('/').pop();
}

function modelEntryIsLoaded(entry = {}) {
  if (!runtime.isLoaded || !runtime.loaded) return false;
  const loaded = runtime.loaded;
  if (entry.url && loaded.url) return entry.url === loaded.url;
  if (entry.repo && loaded.repo && entry.repo === loaded.repo) {
    if (!entry.file || !loaded.file) return true;
    return entry.file === loaded.file;
  }
  if (entry.source === 'local' && loaded.source === 'local') return modelHistoryKey(entry) === modelHistoryKey(loaded);
  return entry.name === loaded.name;
}

async function renderModelHistory() {
  const target = document.getElementById('modelHistory');
  if (!target) return;
  target.innerHTML = '<div class="history-loading"><span class="spinner"></span>Reading local model history…</div>';

  const [cached, recent] = await Promise.all([
    runtime.listCachedModels(),
    Promise.resolve(getRecentModelHistory()),
  ]);
  if (!document.getElementById('modelHistory')) return;

  // Wllama's cache is the source of truth for reloadable HF models. The tiny
  // BlackRiver history only adds friendly names/last-used ordering and records
  // local GGUFs (browser file permissions cannot be silently restored later).
  const recentRemote = recent.filter((item) => item.source !== 'local');
  const recentLocal = recent.filter((item) => item.source === 'local');
  const cachedEnriched = cached.map((entry) => {
    const exact = recentRemote.find((item) => item.url && item.url === entry.url);
    const byRepo = recentRemote.find((item) => !item.url && item.repo && entry.repo && item.repo === entry.repo);
    const remembered = exact || byRepo;
    return {
      ...entry,
      ...(remembered?.name ? { name: remembered.name } : {}),
      lastUsed: remembered?.lastUsed || 0,
      expectedBytes: entry.size || remembered?.expectedBytes || 0,
    };
  });

  const entries = [];
  const seen = new Set();
  const add = (entry) => {
    if (!entry?.name) return;
    const key = modelHistoryKey(entry);
    if (seen.has(key)) return;
    seen.add(key);
    entries.push(entry);
  };

  const loadedRepresentedByCache = runtime.loaded?.source !== 'local' && cachedEnriched.some((entry) => modelEntryIsLoaded(entry));
  if (runtime.loaded && !loadedRepresentedByCache) add({ ...runtime.loaded, lastUsed: Date.now() });
  for (const item of cachedEnriched.sort((a, b) => (b.lastUsed || 0) - (a.lastUsed || 0))) add(item);
  for (const item of recentLocal) add(item);
  // Keep a remote history item only when no actual cached model represents it.
  for (const item of recentRemote) {
    const represented = cachedEnriched.some((entry) =>
      (item.url && entry.url === item.url) ||
      (!item.url && item.repo && entry.repo === item.repo)
    );
    if (!represented) add(item);
  }

  entries.sort((a, b) => {
    const aLoaded = modelEntryIsLoaded(a) ? 1 : 0;
    const bLoaded = modelEntryIsLoaded(b) ? 1 : 0;
    if (aLoaded !== bLoaded) return bLoaded - aLoaded;
    return (b.lastUsed || 0) - (a.lastUsed || 0);
  });

  if (!entries.length) {
    target.innerHTML = '<div class="empty-history">Downloaded Hugging Face models and recently used local GGUFs will appear here.</div>';
    return;
  }

  target.innerHTML = entries.slice(0, 10).map((entry, index) => {
    const loaded = modelEntryIsLoaded(entry);
    const remote = entry.source !== 'local' && !!entry.url;
    const size = entry.expectedBytes || entry.size || (entry.files || []).reduce((sum, file) => sum + (file.size || 0), 0);
    const meta = entry.source === 'local'
      ? `Local GGUF${size ? ` · ${humanBytes(size)}` : ''}`
      : `${entry.repo || 'Hugging Face cache'}${size ? ` · ${humanBytes(size)}` : ''}`;
    const action = loaded
      ? '<span class="history-loaded">Loaded</span>'
      : remote
        ? `<button class="secondary-button history-action" data-history-load="${index}">Load</button>`
        : `<button class="secondary-button history-action" data-history-local="${index}">Choose again</button>`;
    return `<div class="history-model-row">
      <span class="history-model-icon">${icon(entry.source === 'local' ? 'file' : 'download', 16)}</span>
      <span class="history-model-copy"><strong>${escapeHtml(cachedModelDisplayName(entry))}</strong><small>${escapeHtml(meta)}</small></span>
      ${action}
    </div>`;
  }).join('');

  target.querySelectorAll('[data-history-load]').forEach((button) => {
    button.onclick = async () => {
      const entry = entries[Number(button.dataset.historyLoad)];
      if (!entry?.url) return;
      button.disabled = true;
      beginModelLoad(`Loading ${cachedModelDisplayName(entry)} from local cache…`);
      try {
        await runtime.loadFromUrls({
          url: entry.url,
          mmprojUrl: entry.mmprojUrl || undefined,
          name: cachedModelDisplayName(entry),
          repo: entry.repo || '',
          file: entry.file || entry.name,
          expectedBytes: entry.expectedBytes || entry.size || 0,
        });
        setTimeout(() => { closeModal(); refreshRuntimeUi(); }, 420);
      } catch (error) {
        toast(errorMessage(error), 'error');
        button.disabled = false;
      }
    };
  });

  target.querySelectorAll('[data-history-local]').forEach((button) => {
    button.onclick = () => {
      const entry = entries[Number(button.dataset.historyLocal)];
      renderModelsModal('local');
      toast(`Re-select ${cachedModelDisplayName(entry)} to grant this browser access again.`, 'info');
    };
  });
}

