async function collectFolderGGUF(handle, prefix = '', out = []) {
  for await (const [name, child] of handle.entries()) {
    const path = prefix ? `${prefix}/${name}` : name;
    if (child.kind === 'directory') {
      if (!['node_modules', '.git'].includes(name)) await collectFolderGGUF(child, path, out);
    } else if (/\.gguf$/i.test(name)) {
      const file = await child.getFile();
      Object.defineProperty(file, 'relativePath', { value: path, configurable: true });
      out.push(file);
    }
  }
  return out;
}

