const REASONING_LEVELS = Object.freeze(['off', 'low', 'medium', 'high']);
const REASONING_META = Object.freeze({
  off: { label: 'Off', hint: 'Fastest response', budget: null },
  low: { label: 'Low', hint: 'Light reasoning', budget: 512 },
  medium: { label: 'Medium', hint: 'Balanced reasoning', budget: 2048 },
  high: { label: 'High', hint: 'Deeper reasoning', budget: 8192 },
});

function currentReasoningEffort() {
  return store.getReasoningEffort(store.state.mode);
}

function syncReasoningUi() {
  const effort = currentReasoningEffort();
  const index = Math.max(0, REASONING_LEVELS.indexOf(effort));
  const meta = REASONING_META[effort] || REASONING_META.medium;
  els.reasoningRange.value = String(index);
  els.reasoningLabel.textContent = meta.label;
  els.reasoningHint.textContent = meta.hint;
  els.reasoningBudget.textContent = meta.budget
    ? `Up to ${meta.budget.toLocaleString()} reasoning tokens`
    : 'Thinking disabled for this request';
  els.reasoningBtn.title = `Thinking effort: ${meta.label} · Ctrl+Shift+M`;
}

function setReasoningPopover(open) {
  reasoningPopoverOpen = !!open;
  els.reasoningPopover.classList.toggle('hidden', !reasoningPopoverOpen);
  els.reasoningPopover.setAttribute('aria-hidden', String(!reasoningPopoverOpen));
  els.reasoningBtn.setAttribute('aria-expanded', String(reasoningPopoverOpen));
}

function setReasoningEffortFromIndex(index) {
  const effort = REASONING_LEVELS[Math.max(0, Math.min(REASONING_LEVELS.length - 1, Number(index) || 0))];
  store.setReasoningEffort(effort, store.state.mode);
  syncReasoningUi();
}

const VOICE_MODE_LABELS = Object.freeze({
  natural: 'Natural',
  prompt: 'Prompt',
  raw: 'Raw',
});

function loadVoiceSettings() {
  try {
    const saved = JSON.parse(localStorage.getItem(VOICE_SETTINGS_KEY) || 'null') || {};
    return {
      mode: ['natural', 'prompt', 'raw'].includes(saved.mode) ? saved.mode : 'natural',
      styling: ['auto', 'casual', 'semi-casual', 'semi-formal', 'formal'].includes(saved.styling) ? saved.styling : 'auto',
      structure: ['auto', 'structured', 'prose', 'lists'].includes(saved.structure) ? saved.structure : 'auto',
      language: ['auto', 'en', 'fr'].includes(saved.language) ? saved.language : 'auto',
      context: ['auto', 'general', 'work', 'email'].includes(saved.context) ? saved.context : 'auto',
    };
  } catch {
    return { mode: 'natural', styling: 'auto', structure: 'auto', language: 'auto', context: 'auto' };
  }
}

let voiceSettings = loadVoiceSettings();

function saveVoiceSettings() {
  localStorage.setItem(VOICE_SETTINGS_KEY, JSON.stringify(voiceSettings));
}

function resolveVoiceSettings() {
  const mode = voiceSettings.mode;
  // S1-mini's source demo uses semi-formal/prose/general as its defaults. Keep
  // those exact control values for Natural mode; Prompt mode can additionally
  // understand Workspace's Work context through the BlackRiver system prompt.
  const styling = voiceSettings.styling === 'auto' ? 'semi-formal' : voiceSettings.styling;
  const structure = voiceSettings.structure === 'auto'
    ? (mode === 'prompt' && store.state.mode === 'work' ? 'structured' : 'prose')
    : voiceSettings.structure;
  let context = voiceSettings.context;
  if (context === 'auto') context = mode === 'prompt' && store.state.mode === 'work' ? 'work' : 'general';
  return {
    mode,
    styling,
    structure,
    language: voiceSettings.language || 'auto',
    context,
    locale: navigator.language || 'en-US',
    // S1-mini remains the speech cleanup layer. When QwiVer is already resident,
    // Prompt mode delegates the actual prompt architecture to the main model
    // without adding anything to Chat/Work history.
    deferPromptRefine: mode === 'prompt' && runtime.isLoaded,
  };
}

function syncVoiceSettingsUi() {
  els.voiceModeLabel.textContent = VOICE_MODE_LABELS[voiceSettings.mode] || 'Natural';
  els.voiceStyling.value = voiceSettings.styling;
  els.voiceStructure.value = voiceSettings.structure;
  els.voiceLanguage.value = voiceSettings.language;
  els.voiceContext.value = voiceSettings.context;
  els.voiceModePopover.querySelectorAll('[data-voice-mode]').forEach((button) => {
    button.classList.toggle('active', button.dataset.voiceMode === voiceSettings.mode);
  });
  const advancedDisabled = voiceSettings.mode === 'raw';
  els.voiceStyling.disabled = advancedDisabled;
  els.voiceStructure.disabled = advancedDisabled;
  els.voiceLanguage.disabled = false;
  els.voiceContext.disabled = advancedDisabled;
}

function setVoiceModePopover(open) {
  voicePopoverOpen = !!open;
  els.voiceModePopover.classList.toggle('hidden', !voicePopoverOpen);
  els.voiceModePopover.setAttribute('aria-hidden', String(!voicePopoverOpen));
  els.voiceModeButton.setAttribute('aria-expanded', String(voicePopoverOpen));
}

function formatVoiceElapsed(ms = 0) {
  const totalSeconds = Math.floor(Math.max(0, ms) / 1000);
  return `${String(Math.floor(totalSeconds / 60)).padStart(2, '0')}:${String(totalSeconds % 60).padStart(2, '0')}`;
}

function voiceFileLabel(file = '') {
  if (/model_q4f16/i.test(file)) return 'model weights';
  if (/encoder/i.test(file)) return 'speech encoder';
  if (/decoder/i.test(file)) return 'speech decoder';
  if (/tokenizer/i.test(file)) return 'tokenizer';
  if (/config/i.test(file)) return 'configuration';
  return 'model files';
}

function showVoiceSession() {
  clearTimeout(voiceCompletionTimer);
  els.voiceSession.classList.remove('hidden');
  els.voiceBtn.classList.add('active');
  document.querySelector('.composer-shell')?.classList.add('voice-active');
  startVoiceWaveformAnimation();
  requestAnimationFrame(resizeVoiceCanvas);
}

function hideVoiceSession({ preserveText = true } = {}) {
  setVoiceModePopover(false);
  els.voiceSession.classList.add('hidden');
  els.voiceBtn.classList.remove('active', 'recording');
  document.querySelector('.composer-shell')?.classList.remove('voice-active');
  stopVoiceWaveformAnimation();
  if (!preserveText) {
    els.promptInput.value = voiceBaseText;
    autoResizeComposer();
  }
  els.promptInput.readOnly = generating;
  els.voiceProgress.classList.remove('visible', 'indeterminate');
  els.voiceProgress.querySelector('span').style.width = '0%';
  voiceDisplayProgress = 0;
}

function appendVoiceComposerText(base, addition) {
  const clean = String(addition || '').trimStart();
  if (!base) return clean;
  if (!clean) return base;
  const separator = /\s$/.test(base) ? '' : '\n';
  return `${base}${separator}${clean}`;
}

function updateVoiceProgress(message) {
  const event = message.event || {};
  const percent = Number.isFinite(event.progress) ? Math.max(0, Math.min(100, event.progress)) : null;
  els.voiceProgress.classList.add('visible');
  if (percent == null) {
    els.voiceProgress.classList.add('indeterminate');
    els.voiceProgress.removeAttribute('aria-valuenow');
  } else {
    els.voiceProgress.classList.remove('indeterminate');
    voiceDisplayProgress = percent;
    els.voiceProgress.querySelector('span').style.width = `${percent}%`;
    els.voiceProgress.setAttribute('aria-valuenow', String(Math.round(percent)));
  }
  els.voiceStatusTitle.textContent = message.stage === 'normalizer'
    ? 'Loading S1-mini'
    : message.stage === 'asr-fr'
      ? 'Loading French speech recognition'
      : message.stage === 'multilingual-asr'
        ? 'Loading multilingual speech recognition'
        : 'Loading speech recognition';
  const loaded = Number.isFinite(event.loaded) ? humanBytes(event.loaded) : '';
  const total = Number.isFinite(event.total) ? humanBytes(event.total) : '';
  els.voiceStatusDetail.textContent = percent == null
    ? voiceFileLabel(event.file)
    : `${Math.round(percent)}%${loaded && total ? ` · ${loaded} / ${total}` : ''}`;
}

function updateVoiceState(detail = {}) {
  const state = detail.state || voice.state;
  showVoiceSession();
  els.voiceBtn.classList.toggle('recording', state === 'recording');
  els.voiceModeButton.disabled = state === 'transcribing' || state === 'normalizing';
  els.voiceCancelBtn.disabled = state === 'transcribing' || state === 'normalizing';
  els.voiceStopBtn.hidden = state !== 'recording';

  if (state === 'loading') {
    els.voiceStatusTitle.textContent = 'Preparing BlackRiver Voice';
    els.voiceStatusDetail.textContent = 'Downloads once, then stays cached';
    els.voiceProgress.classList.add('visible', 'indeterminate');
    els.voiceProgress.removeAttribute('aria-valuenow');
  } else if (state === 'ready') {
    els.voiceStatusTitle.textContent = detail.label || 'Voice ready';
    els.voiceStatusDetail.textContent = 'Starting microphone…';
  } else if (state === 'recording') {
    els.voiceStatusTitle.textContent = 'Listening';
    els.voiceStatusDetail.textContent = '00:00';
    els.voiceProgress.classList.remove('visible', 'indeterminate');
  } else if (state === 'transcribing') {
    els.voiceStatusTitle.textContent = 'Transcribing';
    els.voiceStatusDetail.textContent = 'Local speech recognition';
    els.voiceProgress.classList.remove('visible', 'indeterminate');
  } else if (state === 'normalizing') {
    els.voiceStatusTitle.textContent = voiceSettings.mode === 'prompt' ? 'Refining prompt' : 'Polishing';
    els.voiceStatusDetail.textContent = 'S1-mini is cleaning the transcript';
    els.voiceProgress.classList.remove('visible', 'indeterminate');
  } else if (state === 'done') {
    els.voiceStatusTitle.textContent = detail.mode === 'raw' ? 'Transcribed locally' : 'Refined locally';
    els.voiceStatusDetail.textContent = detail.mode === 'prompt' ? 'Prompt ready' : detail.mode === 'raw' ? 'Raw transcript ready' : 'S1-mini complete';
  } else if (state === 'error') {
    els.voiceStatusTitle.textContent = 'Voice unavailable';
    els.voiceStatusDetail.textContent = detail.message || 'Could not start local voice';
  }
}

function resizeVoiceCanvas() {
  if (!els.voiceWaveform || els.voiceSession.classList.contains('hidden')) return;
  const rect = els.voiceWaveform.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const scale = Math.min(devicePixelRatio || 1, 2);
  const width = Math.round(rect.width * scale);
  const height = Math.round(rect.height * scale);
  const ctx = els.voiceWaveform.getContext('2d', { alpha: true });
  if (els.voiceWaveform.width !== width || els.voiceWaveform.height !== height || voiceCanvasScale !== scale) {
    els.voiceWaveform.width = width;
    els.voiceWaveform.height = height;
    voiceCanvasScale = scale;
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
  }
  const barCount = Math.max(28, Math.min(72, Math.floor(rect.width / 8)));
  if (voiceLevels.length !== barCount) {
    voiceEnvelopes = Array.from({ length: barCount }, (_, index) => Math.pow(Math.sin((index / (barCount - 1)) * Math.PI), 0.62));
    voiceLevels = voiceEnvelopes.map((envelope) => 0.06 + envelope * 0.08);
  }
}

function startVoiceWaveformAnimation() {
  if (!voiceWaveformFrame && !document.hidden) voiceWaveformFrame = requestAnimationFrame(drawVoiceWaveform);
}

function stopVoiceWaveformAnimation() {
  if (!voiceWaveformFrame) return;
  cancelAnimationFrame(voiceWaveformFrame);
  voiceWaveformFrame = 0;
}

function drawVoiceWaveform(time = 0) {
  voiceWaveformFrame = 0;
  if (els.voiceSession.classList.contains('hidden')) return;
  resizeVoiceCanvas();
  const width = els.voiceWaveform.clientWidth;
  const height = els.voiceWaveform.clientHeight;
  const ctx = els.voiceWaveform.getContext('2d', { alpha: true });
  ctx.clearRect(0, 0, width, height);
  if (!width || !height || !voiceLevels.length) return startVoiceWaveformAnimation();

  const audioData = voice.state === 'recording' && voice.analyser ? voice.waveformData : null;
  if (audioData) voice.analyser.getByteTimeDomainData(audioData);
  const processing = voice.state === 'transcribing' || voice.state === 'normalizing';
  const loading = voice.state === 'loading';
  const center = height / 2;
  const gap = width / voiceLevels.length;
  const barWidth = Math.max(1.6, Math.min(2.8, gap * 0.42));

  for (let i = 0; i < voiceLevels.length; i++) {
    const envelope = voiceEnvelopes[i];
    let target;
    if (audioData) {
      const from = Math.floor((i / voiceLevels.length) * audioData.length);
      const to = Math.max(from + 1, Math.floor(((i + 1) / voiceLevels.length) * audioData.length));
      let energy = 0;
      for (let sample = from; sample < to; sample++) {
        const value = (audioData[sample] - 128) / 128;
        energy += value * value;
      }
      target = Math.min(1, Math.sqrt(energy / (to - from)) * 7.2 + 0.035);
    } else if (processing) {
      const sweep = (Math.sin(time * 0.003 - i * 0.27) + 1) / 2;
      target = 0.07 + envelope * (0.11 + sweep * 0.24);
    } else if (loading) {
      const pulse = (Math.sin(time * 0.0025 - i * 0.19) + 1) / 2;
      target = 0.055 + envelope * (0.07 + pulse * 0.13);
    } else {
      target = 0.045 + envelope * 0.08;
    }
    voiceLevels[i] += (target - voiceLevels[i]) * (audioData ? 0.34 : 0.08);
    const barHeight = Math.max(2.5, voiceLevels[i] * height * 0.78);
    const x = i * gap + (gap - barWidth) / 2;
    const y = center - barHeight / 2;
    let alpha = 0.25 + envelope * 0.43;
    if (audioData) alpha = 0.44 + voiceLevels[i] * 0.52;
    if (loading && voiceDisplayProgress > 0) alpha = (i / Math.max(1, voiceLevels.length - 1)) <= voiceDisplayProgress / 100 ? 0.78 : 0.16;
    ctx.fillStyle = `rgba(226, 232, 240, ${alpha})`;
    ctx.beginPath();
    ctx.roundRect(x, y, barWidth, barHeight, barWidth / 2);
    ctx.fill();
  }
  startVoiceWaveformAnimation();
}

async function startBlackRiverVoice() {
  if (generating) {
    toast('Stop the current generation before using voice.', 'info');
    return;
  }
  if (voice.state === 'recording') return stopBlackRiverVoice();
  if (['loading', 'transcribing', 'normalizing'].includes(voice.state)) return;

  clearTimeout(voiceCompletionTimer);
  voiceBaseText = els.promptInput.value;
  voiceCurrentText = '';
  showVoiceSession();
  syncVoiceSettingsUi();
  els.promptInput.readOnly = true;
  try {
    await voice.startRecording(resolveVoiceSettings());
  } catch (error) {
    if (error?.name === 'AbortError') return;
    els.promptInput.readOnly = false;
    updateVoiceState({ state: 'error', message: errorMessage(error, 'BlackRiver Voice failed.') });
    toast(errorMessage(error, 'BlackRiver Voice failed.'), 'error');
  }
}

async function stopBlackRiverVoice() {
  if (voice.state !== 'recording') return;
  els.voiceStopBtn.disabled = true;
  try {
    const result = await voice.stopRecording(resolveVoiceSettings());
    if (result?.tooShort) {
      toast('Recording was too short.', 'info');
      voiceCompletionTimer = setTimeout(() => hideVoiceSession({ preserveText: false }), 1100);
      return;
    }
    if (result?.noSignal) {
      toast('The microphone was active, but the PCM recording was too quiet. Try speaking closer to the mic.', 'info');
      voiceCompletionTimer = setTimeout(() => hideVoiceSession({ preserveText: false }), 1500);
      return;
    }
    let finalText = result?.cleaned || result?.raw || '';

    if (voiceSettings.mode === 'prompt' && result?.promptBase && finalText && runtime.isLoaded) {
      const cleanedBrief = finalText;

      // The small Voice models have finished. Free their WebGPU residency before
      // asking the already-loaded QwiVer weights to compile the final prompt.
      if (voice.worker && !voice.capture) voice.releaseModels({ reason: 'prompt-refine' });
      voice.setState('normalizing', { label: 'Refining prompt with QwiVer' });
      els.voiceStatusTitle.textContent = 'Refining prompt';
      els.voiceStatusDetail.textContent = 'QwiVer is compiling the spoken brief';
      voiceCurrentText = '';
      els.promptInput.value = appendVoiceComposerText(voiceBaseText, '');
      autoResizeComposer();

      try {
        finalText = await runtime.refinePrompt({
          brief: cleanedBrief,
          mode: store.state.mode,
          styling: voiceSettings.styling,
          structure: voiceSettings.structure,
          language: voiceSettings.language,
        }, (text) => {
          voiceCurrentText = text;
          els.promptInput.value = appendVoiceComposerText(voiceBaseText, text);
          autoResizeComposer();
        });
      } catch (error) {
        console.warn('[BlackRiver Voice] QwiVer prompt refinement failed; keeping cleaned transcript.', error);
        finalText = cleanedBrief;
        toast('Prompt refinement fell back to the cleaned transcript.', 'info');
      }
      voice.setState('done', { label: 'Prompt ready', mode: 'prompt' });
    }

    voiceCurrentText = finalText;
    els.promptInput.value = appendVoiceComposerText(voiceBaseText, finalText);
    autoResizeComposer();
    if (!finalText) {
      toast('Speech signal captured, but transcription returned no text. Try again.', 'info');
    }
    voiceCompletionTimer = setTimeout(() => hideVoiceSession({ preserveText: true }), finalText ? 820 : 1500);
  } catch (error) {
    if (error?.name !== 'AbortError') {
      updateVoiceState({ state: 'error', message: errorMessage(error, 'BlackRiver Voice failed.') });
      toast(errorMessage(error, 'BlackRiver Voice failed.'), 'error');
    }
  } finally {
    els.voiceStopBtn.disabled = false;
    els.promptInput.readOnly = generating;
    if (!generating) els.promptInput.focus();
  }
}

async function cancelBlackRiverVoice() {
  clearTimeout(voiceCompletionTimer);
  try {
    if (voice.state === 'loading') voice.releaseModels({ reason: 'cancel' });
    else await voice.cancelRecording();
  } catch {}
  hideVoiceSession({ preserveText: false });
  els.promptInput.readOnly = generating;
  if (!generating) els.promptInput.focus();
}

async function sendPrompt() {
  if (generating) return;
  if (['loading', 'recording', 'transcribing', 'normalizing'].includes(voice.state)) {
    toast('Finish voice input before sending.', 'info');
    return;
  }
  const text = els.promptInput.value.trim();
  if (!text && !pendingAttachment) return;
  // Voice lives in a completely separate worker. Once the user actually sends
  // the prompt, release the short-lived Moonshine/S1 WebGPU residency before
  // QwiVer starts generating. This never unloads or mutates the Wllama model.
  if (!els.voiceSession.classList.contains('hidden')) hideVoiceSession({ preserveText: true });
  if (voice.worker && !voice.capture) voice.releaseModels({ reason: 'generation' });
  if (!runtime.isLoaded) {
    renderModelsModal('recommended');
    toast('Choose a model first.', 'info');
    return;
  }

  const reasoningProfile = currentReasoningEffort();
  generating = true;
  activeTurnStart = performance.now();
  lastInferenceMetrics = null;
  els.sendBtn.classList.add('hidden');
  els.stopBtn.classList.remove('hidden');
  els.voiceBtn.disabled = true;
  els.reasoningBtn.disabled = true;
  // Keep the composer readable and selectable while inference is running. The
  // send button becomes Stop just like a polished chat client; we do not freeze the UI.
  els.promptInput.readOnly = true;

  let attachment = null;
  if (pendingAttachment) {
    const type = pendingAttachment.type.startsWith('image/') ? 'image' : pendingAttachment.type.startsWith('audio/') ? 'audio' : null;
    if (type) attachment = { type, data: await pendingAttachment.arrayBuffer() };
  }

  const file = pendingAttachment;
  store.addMessage({ role: 'user', content: text, attachmentName: file?.name || null });
  const assistantMessage = store.addMessage({
    role: 'assistant',
    content: '',
    reasoning: '',
    tools: [],
    live: true,
    phase: 'prefill',
    activity: 'Reading context',
    elapsedMs: 0,
    metrics: null,
    reasoningProfile,
  });
  setAttachment(null);
  els.promptInput.value = '';
  autoResizeComposer();
  renderConversation();
  startActivityTicker(assistantMessage);

  try {
    const conv = store.activeConversation;
    const result = await harness.run({
      mode: store.state.mode,
      messages: conv.messages.filter((m) => m.id !== assistantMessage.id),
      attachment,
      conversationId: conv.id,
      reasoningProfile,
      onText: (content) => {
        assistantMessage.content = content;
        queueAssistantDomUpdate(assistantMessage);
      },
      onReasoning: (reasoning) => {
        assistantMessage.reasoning = reasoning;
        queueAssistantDomUpdate(assistantMessage);
      },
      onTool: (event) => {
        assistantMessage.tools ||= [];
        assistantMessage.tools.push({ phase: event.phase, name: event.name, args: compactToolPayload(event.args), result: compactToolPayload(event.result) });
        queueAssistantDomUpdate(assistantMessage);
      },
      onArtifact: (artifact) => renderArtifact(artifact),
      onState: (state) => {
        const next = typeof state === 'string' ? { phase: 'thinking', label: state } : state || {};
        assistantMessage.phase = next.phase || assistantMessage.phase || 'thinking';
        assistantMessage.activity = next.label || assistantMessage.activity || 'Thinking';
        queueAssistantDomUpdate(assistantMessage);
      },
      onMetrics: (metrics) => {
        assistantMessage.metrics = metrics;
        updateInferenceCaption(metrics);
      },
      approve: async ({ summary, name }) => window.confirm(`BlackRiver Work wants to ${summary || name}.\n\nAllow this change?`),
    });
    assistantMessage.content = result.content || assistantMessage.content || 'Done.';
    assistantMessage.reasoning = result.reasoning || assistantMessage.reasoning || '';
    assistantMessage.metrics = result.metrics || assistantMessage.metrics || null;
  } catch (e) {
    if (e.name !== 'AbortError') assistantMessage.content = `Error: ${errorMessage(e, 'Wllama runtime failed.')}`;
  } finally {
    assistantMessage.elapsedMs = performance.now() - activeTurnStart;
    assistantMessage.live = false;
    assistantMessage.phase = 'done';
    assistantMessage.activity = '';
    generating = false;
    stopActivityTicker();
    els.sendBtn.classList.remove('hidden');
    els.stopBtn.classList.add('hidden');
    els.voiceBtn.disabled = false;
    els.reasoningBtn.disabled = false;
    els.promptInput.readOnly = false;
    if (assistantMessage.metrics) updateInferenceCaption(assistantMessage.metrics);
    else refreshRuntimeUi();
    store.save();
    updateAssistantDom(assistantMessage, { streaming: false });
    els.promptInput.focus();
  }
}

const compactViewport = window.matchMedia('(max-width: 900px)');
let desktopSidebarCollapsed = document.body.classList.contains('sidebar-collapsed');

function isCompactViewport() {
  return compactViewport.matches;
}

function syncSidebarA11y() {
  const mobile = isCompactViewport();
  const open = mobile && document.body.classList.contains('mobile-sidebar-open');
  if (els.mobileSidebarButton) els.mobileSidebarButton.setAttribute('aria-expanded', String(open));
  els.sidebar.setAttribute('aria-hidden', mobile && !open ? 'true' : 'false');
  // Prevent an off-canvas drawer from remaining keyboard-focusable.
  if ('inert' in els.sidebar) els.sidebar.inert = mobile && !open;
}

function openMobileSidebar() {
  if (!isCompactViewport()) return;
  document.body.classList.remove('sidebar-collapsed');
  document.body.classList.add('mobile-sidebar-open');
  syncSidebarA11y();
}

function closeMobileSidebar() {
  document.body.classList.remove('mobile-sidebar-open');
  syncSidebarA11y();
}

function toggleMobileSidebar() {
  if (!isCompactViewport()) return;
  if (document.body.classList.contains('mobile-sidebar-open')) closeMobileSidebar();
  else openMobileSidebar();
}

function setSidebarCollapsed(collapsed) {
  if (isCompactViewport()) {
    closeMobileSidebar();
    return;
  }
  desktopSidebarCollapsed = !!collapsed;
  document.body.classList.toggle('sidebar-collapsed', desktopSidebarCollapsed);
  const toggle = document.getElementById('collapseSidebar');
  const label = desktopSidebarCollapsed ? 'Expand sidebar' : 'Collapse sidebar';
  toggle.setAttribute('aria-label', label);
  toggle.title = label;
  syncSidebarA11y();
}

function syncResponsiveShell() {
  if (isCompactViewport()) {
    // Mobile/tablet uses a proper off-canvas drawer, never the desktop icon rail.
    document.body.classList.remove('sidebar-collapsed', 'mobile-sidebar-open');
  } else {
    document.body.classList.remove('mobile-sidebar-open');
    document.body.classList.toggle('sidebar-collapsed', desktopSidebarCollapsed);
  }
  syncSidebarA11y();
}

function renderAll() {
  setMode(store.state.mode, { persist: false });
  renderRecents();
  renderConversation();
  els.projectLabel.textContent = project.name || 'Choose project';
  refreshRuntimeUi();
  const activeArtifact = artifacts.get(artifacts.activeId);
  const activeConv = store.activeConversation;
  if (activeArtifact && store.state.mode === 'work' && activeArtifact.conversationId === activeConv?.id) renderArtifact(activeArtifact);
  else hideArtifactPane({ preserveActive: true });
}

