document.getElementById('downloadArtifact').onclick = () => {
  const item = artifacts.get(artifacts.activeId);
  if (!item) return;
  const ext = item.type === 'html' ? 'html' : item.language || (item.type === 'markdown' ? 'md' : 'txt');
  const blob = new Blob([item.content], { type: item.type === 'html' ? 'text/html' : 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${item.title.replace(/[^a-z0-9-_]+/gi, '-').replace(/^-|-$/g, '') || 'artifact'}.${ext}`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

voice.addEventListener('state', (event) => updateVoiceState(event.detail));
voice.addEventListener('progress', (event) => updateVoiceProgress(event.detail));
voice.addEventListener('timer', (event) => {
  if (voice.state === 'recording') els.voiceStatusDetail.textContent = formatVoiceElapsed(event.detail.elapsedMs);
});
voice.addEventListener('stream', (event) => {
  voiceCurrentText = event.detail.text || '';
  els.promptInput.value = appendVoiceComposerText(voiceBaseText, voiceCurrentText);
  autoResizeComposer();
});
voice.addEventListener('phase', (event) => {
  const phase = event.detail?.phase;
  const label = event.detail?.label;
  if (label && ['fallback-asr', 'transcribing', 'normalizing', 'loading-asr', 'loading-asr-fr', 'loading-multilingual-asr'].includes(phase)) {
    els.voiceStatusTitle.textContent = label;
    if (phase === 'normalizing') {
      els.voiceStatusDetail.textContent = label === 'Cleaning speech' ? 'Removing speech clutter' : 'S1-mini prompt architect';
    }
  }
});
voice.addEventListener('stream-reset', () => {
  voiceCurrentText = '';
  els.promptInput.value = appendVoiceComposerText(voiceBaseText, '');
  autoResizeComposer();
});
voice.addEventListener('audio-metrics', (event) => {
  const m = event.detail || {};
  console.debug(
    '[BlackRiver Voice] PCM metrics',
    { duration: m.duration, rms: m.originalRms, peak: m.originalPeak, gain: m.gain },
  );
});
voice.addEventListener('error', (event) => {
  updateVoiceState({ state: 'error', message: event.detail.message });
});
voice.addEventListener('released', () => {
  // Voice's dedicated worker is intentionally disposable. Releasing it frees
  // its WebGPU resources without touching the Wllama/QwiVer worker or context.
  if (els.voiceSession.classList.contains('hidden')) els.voiceBtn.classList.remove('active', 'recording');
});

runtime.addEventListener('status', (event) => {
  refreshRuntimeUi(event.detail);
  setModelLoadProgress(event.detail);
  if (event.detail.state === 'ready') {
    if (event.detail.loaded) rememberModel(event.detail.loaded);
    toast(`${event.detail.message}`, 'success');
  }
  if (event.detail.state === 'error') toast(event.detail.message || 'Wllama runtime error', 'error');
});
runtime.addEventListener('hardware', refreshRuntimeUi);
project.addEventListener('project', () => { els.projectLabel.textContent = project.name || 'Choose project'; renderEmptyState(); });
artifacts.addEventListener('open', (e) => renderArtifact(e.detail));
artifacts.addEventListener('created', (e) => renderArtifact(e.detail));
artifacts.addEventListener('updated', (e) => renderArtifact(e.detail));
store.addEventListener('change', renderRecents);

// Initialize sampling/runtime from persisted settings.
