runtime.setSampling({ max_tokens: store.state.settings.maxTokens || 8192, temperature: store.state.settings.temperature ?? 0.7 });
runtime.probeWebGPU().finally(refreshRuntimeUi);
compactViewport.addEventListener?.('change', syncResponsiveShell);
