const HF_API = 'https://huggingface.co/api';
const HF_BASE = 'https://huggingface.co';

async function hfFetch(path) {
  const response = await fetch(`${HF_API}${path}`, {
    headers: { Accept: 'application/json' },
  });
  if (!response.ok) throw new Error(`Hugging Face request failed (${response.status})`);
  return response.json();
}

export async function searchHuggingFace(query, limit = 18) {
  const q = encodeURIComponent(query.trim());
  if (!q) return [];
  const data = await hfFetch(`/models?search=${q}&filter=gguf&sort=downloads&direction=-1&limit=${limit}&full=true`);
  return data.map((m) => ({
    id: m.id,
    downloads: m.downloads || 0,
    likes: m.likes || 0,
    updated: m.lastModified,
    tags: m.tags || [],
    private: !!m.private,
  }));
}

export async function getRepoGGUFFiles(repo) {
  const repoPath = repo.split('/').map(encodeURIComponent).join('/');
  const data = await hfFetch(`/models/${repoPath}?blobs=true`);
  const siblings = data.siblings || [];
  return siblings
    .filter((f) => /\.gguf$/i.test(f.rfilename || ''))
    .map((f) => ({
      name: f.rfilename,
      size: f.size || f.lfs?.size || 0,
      isProjector: /(^|\/)mmproj/i.test(f.rfilename),
      url: resolveHFUrl(repo, f.rfilename),
    }));
}

export function resolveHFUrl(repo, filename) {
  return `${HF_BASE}/${repo}/resolve/main/${filename.split('/').map(encodeURIComponent).join('/')}?download=true`;
}

export function humanBytes(bytes = 0) {
  if (!bytes) return 'size unknown';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
  }
  return `${value >= 10 || i === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[i]}`;
}
