const STORAGE_KEY = 'blackriver.workspace.v06';
const LEGACY_KEYS = ['blackriver.workspace.v05'];

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function normalizeState(saved) {
  const conversations = Array.isArray(saved?.conversations) ? saved.conversations : [];
  const mode = saved?.mode === 'work' ? 'work' : 'chat';
  const activeConversationId = saved?.activeConversationId || null;
  const activeByMode = {
    chat: saved?.activeByMode?.chat || null,
    work: saved?.activeByMode?.work || null,
  };

  // Migrate the old single-active-conversation schema without changing any
  // conversation content. A conversation's mode is now immutable: switching the
  // Chat / Work tabs swaps context lanes instead of rewriting the same context.
  const oldActive = conversations.find((c) => c.id === activeConversationId);
  if (oldActive?.id) activeByMode[oldActive.mode === 'work' ? 'work' : 'chat'] = oldActive.id;
  for (const lane of ['chat', 'work']) {
    if (!activeByMode[lane] || !conversations.some((c) => c.id === activeByMode[lane] && (c.mode === 'work' ? 'work' : 'chat') === lane)) {
      activeByMode[lane] = conversations.find((c) => (c.mode === 'work' ? 'work' : 'chat') === lane)?.id || null;
    }
  }

  return {
    conversations,
    activeConversationId: activeByMode[mode] || null,
    activeByMode,
    mode,
    settings: {
      context: saved?.settings?.context || 32768,
      maxTokens: saved?.settings?.maxTokens || 8192,
      temperature: saved?.settings?.temperature ?? 0.7,
      reasoningByMode: {
        chat: ['off', 'low', 'medium', 'high'].includes(saved?.settings?.reasoningByMode?.chat)
          ? saved.settings.reasoningByMode.chat
          : 'medium',
        work: ['off', 'low', 'medium', 'high'].includes(saved?.settings?.reasoningByMode?.work)
          ? saved.settings.reasoningByMode.work
          : 'high',
      },
    },
  };
}

export class WorkspaceStore extends EventTarget {
  constructor() {
    super();
    this.state = this.load();
  }

  load() {
    for (const key of [STORAGE_KEY, ...LEGACY_KEYS]) {
      try {
        const saved = JSON.parse(localStorage.getItem(key) || 'null');
        if (saved?.conversations) {
          const normalized = normalizeState(saved);
          if (key !== STORAGE_KEY) localStorage.setItem(STORAGE_KEY, JSON.stringify(normalized));
          return normalized;
        }
      } catch {}
    }
    return normalizeState(null);
  }

  save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state));
    this.dispatchEvent(new Event('change'));
  }

  get activeConversation() {
    return this.state.conversations.find((c) => c.id === this.state.activeConversationId) || null;
  }

  switchMode(mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    this.state.mode = lane;
    this.state.activeConversationId = this.state.activeByMode?.[lane] || null;
    this.save();
    return this.activeConversation;
  }

  newConversation(mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    const conversation = {
      id: uid(),
      title: 'New chat',
      mode: lane,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      messages: [],
    };
    this.state.conversations.unshift(conversation);
    this.state.activeByMode ||= { chat: null, work: null };
    this.state.activeByMode[lane] = conversation.id;
    this.state.activeConversationId = conversation.id;
    this.state.mode = lane;
    this.save();
    return conversation;
  }

  activate(id) {
    const conv = this.state.conversations.find((c) => c.id === id) || null;
    if (!conv) return null;
    const lane = conv.mode === 'work' ? 'work' : 'chat';
    this.state.activeConversationId = id;
    this.state.activeByMode ||= { chat: null, work: null };
    this.state.activeByMode[lane] = id;
    this.state.mode = lane;
    this.save();
    return conv;
  }

  deleteConversation(id) {
    const conv = this.state.conversations.find((c) => c.id === id);
    this.state.conversations = this.state.conversations.filter((c) => c.id !== id);
    if (conv) {
      const lane = conv.mode === 'work' ? 'work' : 'chat';
      if (this.state.activeByMode?.[lane] === id) {
        this.state.activeByMode[lane] = this.state.conversations.find((c) => (c.mode === 'work' ? 'work' : 'chat') === lane)?.id || null;
      }
    }
    this.state.activeConversationId = this.state.activeByMode?.[this.state.mode] || null;
    this.save();
  }

  ensureConversation() {
    const active = this.activeConversation;
    if (active && (active.mode === 'work' ? 'work' : 'chat') === this.state.mode) return active;
    return this.newConversation(this.state.mode);
  }

  addMessage(message) {
    const conv = this.ensureConversation();
    conv.messages.push({ id: uid(), createdAt: Date.now(), ...message });
    conv.updatedAt = Date.now();
    if (message.role === 'user' && conv.title === 'New chat') {
      conv.title = message.content.replace(/\s+/g, ' ').trim().slice(0, 52) || 'New chat';
    }
    this.save();
    return conv.messages[conv.messages.length - 1];
  }

  updateMessage(id, patch) {
    const conv = this.activeConversation;
    const msg = conv?.messages.find((m) => m.id === id);
    if (!msg) return;
    Object.assign(msg, patch);
    conv.updatedAt = Date.now();
    this.save();
  }

  getReasoningEffort(mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    return this.state.settings?.reasoningByMode?.[lane] || (lane === 'work' ? 'high' : 'medium');
  }

  setReasoningEffort(value, mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    const effort = ['off', 'low', 'medium', 'high'].includes(value) ? value : (lane === 'work' ? 'high' : 'medium');
    this.state.settings ||= {};
    this.state.settings.reasoningByMode = {
      chat: this.state.settings.reasoningByMode?.chat || 'medium',
      work: this.state.settings.reasoningByMode?.work || 'high',
      [lane]: effort,
    };
    this.save();
    return effort;
  }

  updateSettings(patch) {
    this.state.settings = {
      ...this.state.settings,
      ...patch,
      ...(patch.reasoningByMode ? {
        reasoningByMode: {
          ...(this.state.settings.reasoningByMode || { chat: 'medium', work: 'high' }),
          ...patch.reasoningByMode,
        },
      } : {}),
    };
    this.save();
  }
}
